    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); late, tolerate residuals
    // that leave room for future items, so weight flips smoothly.
    let prn = pr / cap; // normalized post-residual in [0,1]
    let w_tight = 1.0 - progress;      // weight favoring tight packing early
    let w_room = progress;             // weight favoring usable slack later
    score += w_tight * 12.0 * prn * prn;
    score -= w_room * 6.0 * prn * (1.0 - prn) * (1.0 - prn);

    // Smooth interaction: item_size vs bin_residual fill fraction.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill * (1.0 - progress);

    // Lookahead: reward post_residual that can host next item (smooth kernel).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let k = (diff / 10.0) * (diff / 10.0);
        score -= 10.0 * (-k) * (1.0 - progress);
