pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division bands
    let pr = post_residual;
    let band = pr / 10; // 0..=9 harmonic band
    let residue = pr % 10;

    // Reward small post residuals, with harmonic discounts at "nice" sizes
    // (multiples of 10 are more reusable by typical item sizes)
    if residue == 0 {
        score -= 4.0 + band as f64 * 0.5;
    } else if residue == 5 {
        score -= 2.0;
    } else {
        score += residue as f64 * 0.15; // ragged leftovers penalized
    }

    // Dead-space cliff: residuals too small for the minimum item size (1)
    // but small residuals are still usable; penalize very tight unusable slivers
    if pr > 0 && pr < 3 {
        score += 6.0;
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic: next item leaves a multiple-of-10 remainder => good
            let nxt_res = pr - next_item_size;
            let harm = if nxt_res % 10 == 0 { 3.0 } else if nxt_res % 5 == 0 { 1.5 } else { 0.0 };
            score -= harm + slack * 0.05;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - pr) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: keep empty bins neutral-to-slightly-high
    // unless current fit is terrible
    if bin_residual == bin_capacity {
        score = 12.0 + post_residual as f64 * 0.0
            - (if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 0.0 });
        // scale with stream progress: later, prefer packing into open bins less
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 3.0;
        score -= open_bins_count as f64 * 0.3;
        // if mean residual across bins is large, opening new bin is wasteful
        score += (mean_residual / cap).max(0.0) * 6.0;
    }

    // Global waste pressure: bins with residual far from mean are either
    // hoarders (big residual) or nearly full; slight pull toward mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Perfect fit celebration
    if pr == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

