    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // all open bins would waste badly or there are no fitting bins.
    if bin_residual == bin_capacity {
        let dead_space_pressure = if fitting_bins_count == 0 {
            100.0
        } else {
            // estimate worst-case waste if forced into an existing bin:
            // we don't know other residuals, use mean_residual as proxy
