pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: gaps too small for any item (min size 1..100 unknown,
    // use next_item_size lookahead and a conservative small-gap threshold).
    let gap_floor = next_item_size.max(1);
    if post_residual > 0 && post_residual < gap_floor {
        score += 60.0; // dead space that even the lookahead item cannot use
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    }

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Reward perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is excellent.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 15.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when all open bins would waste badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progression and open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * pressure + 10.0 * progress;
        // But if current item + next item fit perfectly in a fresh bin, encourage it.
        if item_size + next_item_size == bin_capacity {
            score -= 45.0;
        }
    }

    // Slight preference to keep mean residual balanced (avoid one huge-gap bin and many tight ones).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // 2-step lookahead: if next item exactly fills post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Penalize leaving residual that the next item only partially uses,
            // scaled by how much slack would remain after the next item.
            let leftover = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - leftover / (bin_capacity as f64));
        } else {
            // Next item cannot fit in the residual: penalize proportionally to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 6.0 * (overflow / 100.0);
        }
    } else {
        // Last item: any residual is pure waste; reward filling as much as possible.
        score += 0.5 * post_residual as f64;
    }

    // Compare residual to mean residual across open bins.
    // Bins with residual below mean are "more filled": prefer placing there
    // (best-fit style), bins above mean are looser.
    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.4 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit,
    // especially early/mid stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
            // A fresh bin has full residual; if next item would fit perfectly
            // in the residual left here, a new bin is less bad.
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild preference for consolidating when many bins are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: fraction of stream completed
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Tightness of the fit: reward near-perfect fills
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (wasted capacity)
    score += 0.08 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Lookahead coupling: if next item fits the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // post-residual too small for next item: penalize proportionally to waste
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Bonus if this bin becomes nearly full and next item opens fresh elsewhere
        if post_residual < next_item_size && post_residual < 10 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: mild penalty for using a loose one
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: prefer filling bins when many bins are open (reduce fragmentation)
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Deviation from mean residual: bins far below mean residual (tighter) preferred
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early phase: keep bins flexible (avoid creating tiny residuals early)
    let flexibility = post_residual as f64 / bin_capacity as f64;
    score += (1.0 - t) * 10.0 * (0.15 - flexibility).max(0.0) * 10.0;
    // Late phase: aggressive consolidation, reward any fill
    score -= t * 12.0 * fit_ratio;

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Default cost of opening a new bin grows over time and with open bins
        score += 15.0 + t * 10.0 + (open_bins_count as f64) * 0.3;
        // But if no open bin fits (pressure), new bin must be cheap
        if pressure > 0.0 {
            score -= 100.0;
        }
        // Late in stream, prefer new bin over leaving dead space
        if t > 0.8 && post_residual_of_best_unknown(fit_ratio) {
            score -= 5.0;
        }
    }

    score
}

#[inline]
fn post_residual_of_best_unknown(_fit_ratio: f64) -> bool { true }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 20.0 * poly;

    // Penalize large post residuals late in the stream (wasted space compounds)
    score += 15.0 * norm_pr * norm_pr * progress;

    // Reward tight fits smoothly via cubic decay of post_residual
    score -= 10.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead coupling: penalize if post_residual can't fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / cap * (0.5 + progress);
        } else {
            score -= 5.0 * (pr - ns) / cap;
        }
    }

    // New-bin candidate: neutral baseline with mild smooth preference early
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * progress + 2.0 * norm_pr;
    }

    // Mean residual interaction: prefer bins deviating below mean residual
    score += 4.0 * (mean_residual - pr) / cap;

    // Open bins pressure: mildly discourage scattering when many bins are open
    score += 0.3 * open_bins_count as f64 * norm_pr * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual ----
    // Class residuals into buckets of size 10 (capacity fractions).
    // Small-but-reusable residuals (<= 20) are fine only if the next item
    // can actually use them; otherwise they are dead space -> penalize.
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => {
            // Perfect or near-perfect fit: strongly reward.
            score -= 60.0;
        }
        1 => {
            // Residual 10..=19: only valuable if next item fits into it.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 35.0;
            } else {
                // Dead space smaller than the minimum item size (1) is rare,
                // but small leftovers are still weakly penalized.
                score += 8.0;
            }
        }
        2 => {
            // Residual 20..=29: good harbor for medium items.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 25.0;
            } else {
                score += 4.0;
            }
        }
        3 => {
            // Residual 30..=39: check parity harmony with next item.
            if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
                score -= 20.0; // exact division -> future perfect fill
            }
        }
        4 | 5 => {
            // Mid-class residuals: mildly reward if next item nests.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 10.0;
            }
        }
        _ => {
            // Large residuals: bin barely used; penalize lightly so that
            // tighter bins are preferred, but keep it usable as fallback.
            score += 3.0;
        }
    }

    // ---- Last-chance bonus ----
    // If this is the ONLY bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // ---- New-bin candidate handling ----
    // Brand-new empty bin: prefer it only when the item is large relative
    // to capacity (harmonic fraction > 1/2) or nothing fits well.
    if bin_residual == bin_capacity {
        let fraction = item_size as f64 / bin_capacity as f64;
        if fraction > 0.5 {
            score -= 15.0; // big items deserve fresh bins
        } else {
            score += 25.0; // small items should go into open bins
        }
        // If many bins are open with slack, discourage spreading thin.
        if mean_residual > 30.0 {
            score += 10.0;
        }
    }

    // ---- Lookahead coupling: does next item fit here after this one? ----
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward chains where consecutive items stack harmonically.
        score -= 12.0;
        // Extra reward for exact modular harmony.
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; residual is likely dead -> penalize
        // proportionally to stream progress (late dead space is costly).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (0.5 + progress);
    }

    // ---- Waste density: penalize residual per unit of item placed ----
    if item_size > 0 {
        score += (post_residual as f64) / (item_size as f64) * 5.0;
    }

    // ---- Congestion term: when many bins compete, prefer tight fits more ----
    if open_bins_count > 3 {
        score += (post_residual as f64) * (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest future item (1..=min_item) are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0;
    }
    // Small-ish gaps that likely can't fit typical next items: graded penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item cannot fit in the post residual, mild penalty (bin becomes dead).
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // But if this is the last item or current fit is terrible, opening is fine.
        if next_item_size == 0 {
            score -= 10.0;
        }
        if post_residual_of_others_proxy(mean_residual) > item_size as f64 {
            score -= 8.0;
        }
    } else {
        // Using an existing bin slightly relieves open-bin pressure.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (compact the emptier space into fewer bins).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Early in stream, be slightly more willing to open bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

fn post_residual_of_others_proxy(mean_residual: f64) -> f64 {
    mean_residual
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual).
    // Reward placements where the lookahead item also fits exactly into the leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item packing chain
        } else if post_residual >= next_item_size {
            // leftover remains usable by the next item: mild reward, scaled by how much stays
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space proportionally
            score += 4.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage closing bins out (tight fits) rather than spreading.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).sqrt();
        // reward bins below mean residual (they are the "emptiest" -> fill them)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Early stream: slightly favor reusing bins to establish tight packing;
    // late stream: strongly avoid opening new bins (fewer bins matter most).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 10.0 + 20.0 * progress;
        // but if item is huge and no tight fit exists, opening is acceptable:
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    } else {
        score -= 5.0 * progress; // reuse bonus grows over time
    }

    // Nonlinear nudge toward exact-fill completions.
    if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling: base term plus non-linear progress interaction
    let mut score = x * (1.0 + 0.9 * progress);
    score += 0.55 * x * x * (1.0 - progress);
    score += 1.3 * x * x * x * progress;

    // Dead-space penalty grows quadratically for mid-range waste
    let dead = x * (1.0 - x);
    score += 0.8 * dead * dead;

    // Prefer tight fits: reward small post_residual non-linearly
    score -= 1.1 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // Lookahead: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 1.5 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 0.6 * ((nxt - pr) / cap);
        }
    }

    // Mean residual divergence: penalize bins far from the fleet average
    score += 0.25 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: keep it attractive early, less so late
    if bin_residual == bin_capacity {
        score = 0.9 + 1.4 * progress - 0.4 * (fitting_bins_count as f64).ln().max(0.0);
        if fitting_bins_count <= 1 {
            score -= 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item relative to capacity: which capacity fraction class does it belong to?
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    let third = bin_capacity / 3;        // 33

    // Integer-division class of post_residual: small post_residual = tight fit (good).
    let post_class = post_residual / quarter; // 0..=4 harmonic band of leftover space

    // Reward tight fits: post_residual in the lowest band gets a strong subtraction.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_class == 0 {
        score -= 25.0; // very tight fit (post_residual < 25)
    } else if post_class == 1 {
        score -= 8.0;  // moderate fit
    } else if post_class == 2 {
        // post_residual in [50,75): large dead space, penalize unless item is huge
        score += 6.0;
    } else {
        score += 12.0; // worst band: more than 75 wasted potential
    }

    // Modulo-arithmetic harmony: does post_residual align with common small item sizes?
    // If the leftover is itself a plausible item size (multiple of 5 or 10), future items may fill it.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: can the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it nests.
            let nest_ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nest_ratio;
            // Extra harmonic bonus if next item exactly matches post_residual class
            if next_item_size / quarter.max(1) == post_class {
                score -= 3.0;
            }
        } else {
            // Next item cannot use the leftover: penalize big leftovers more.
            score += 3.0 + 0.05 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral base: an empty bin leaves max flexibility.
        score = post_residual as f64; // = capacity
        // Penalize opening new bins when existing bins already fit well.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If mean residual across open bins is large, definitely avoid a new bin.
        if mean_residual > half as f64 {
            score += 15.0;
        }
    }

    // Slight preference for filling bins that are already mostly full (low residual).
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Open-bin count pressure: many open bins -> prefer existing bins over new ones.
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are penalized heavily
    // since they are unlikely to be usable by future items (sizes >= 1).
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gap in the "dead zone" (1..=9) is nearly unusable: strong penalty.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            // Larger leftovers remain usable; mild reward.
            score -= 6.0;
        }
        // Non-linear coupling: penalize proportional waste for tight fits
        // that still leave a sliver.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.8 && post_residual < 15 {
            score += 12.0 * (fill_ratio - 0.8);
        }
    } else {
        // Perfect fit: maximal reward.
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // This bin's leftover will be dead for the next item.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (favor bins with small residuals relative to mean).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);
    if bin_residual as f64 > mean_residual {
        score += 5.0 * pressure;
    } else {
        score -= 3.0 * pressure;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the
    // item is large and no good fit exists; otherwise discourage it.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // forced: no open bin fits
        } else if item_frac > 0.5 {
            score -= 2.0; // large item: a fresh bin is reasonable
        } else {
            score += 15.0 + 20.0 * (1.0 - item_frac); // small item: keep it in open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match of post_residual with next item size (2-step lookahead).
    let pr = post_residual as f64;
    let nx = next_item_size as f64;
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (pr - nx).abs();
        if diff == 0.0 {
            score -= 1000.0; // perfect 2-step match: place here
        } else {
            score -= (100.0 / diff).min(50.0); // near-match bonus decaying with distance
        }
    } else if next_item_size > post_residual {
        // Next item cannot fit in this bin's leftover: penalize proportionally.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable dead space (fragmentation) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 - 3.0 * post_residual as f64;
    }

    // Reward leaving residuals close to the mean (balance across bins).
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild penalty for opening new bins early in the stream; new-bin candidate
    // (bin_residual == bin_capacity) gets a baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (step_index as f64 / (total_items as f64).max(1.0));
        score += 2.0 * open_bins_count as f64;
    }

    // Encourage tight fits overall: prefer smaller bin_residual before placement.
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // Lookahead: reward if leftover can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else {
            score -= 80.0 * (1.0 - gap as f64 / 50.0).max(0.0);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that cannot host next item: mild penalty scaled by dead size.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and open bins are fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Open new bin when item is big, open bins are few or fragmented.
        let penalty = 60.0
            + 150.0 * fragmentation
            - 120.0 * large_item
            + 40.0 * (open_bins_count as f64).ln().max(0.0)
            - 30.0 * progress;
        score += penalty.max(0.0);
    } else {
        // Prefer bins whose residual deviates below mean (tighter bins first).
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;
    }

    // Slight preference for earlier-opened (more filled) bins is implicit via post_residual.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill = 1.0 - pr / cap; // fraction of bin used after placement

    // Base: prefer tight fits; polynomial coupling with progress makes
    // tightness increasingly valuable as the stream advances.
    let mut score = pr * (1.0 + 0.9 * progress * progress) - 25.0 * fill * (0.5 + progress);

    // Dead-space penalty: non-linear in wasted residual (small residuals are fine).
    let waste = pr / cap;
    score += 12.0 * waste * waste * (1.0 + progress);

    // Reward using an existing bin vs. opening a new one, scaled by stream progress.
    if bin_residual == bin_capacity && item_size > 0 {
        // New-bin candidate: only attractive if it enables a near-perfect pack
        // or few alternatives exist.
        let perfect = (pr as f64).abs() < f64::EPSILON;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 8.0 - 6.0 * scarcity - (if perfect { 20.0 } else { 0.0 }) * (0.5 + progress);
        score += 5.0 * (1.0 - progress);
    } else {
        score -= 4.0 + 3.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.6 + 0.4 * progress);
    }

    // Lookahead coupling: reward leaving residual close to the next item size
    // (smooth quadratic attraction).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap) * (0.4 + 0.6 * progress);
    }

    // Mild pressure toward consolidating among many open bins.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);

    // Slight preference toward bins whose residual is below average (denser bins).
    score += 0.5 * ((pr - mean_residual) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of
    // common item sizes are more likely to be filled later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_frac = (bin_residual as f64) / cap; // how full the bin already is

    // Reward tight fits (small post residual) super-linearly.
    score -= (1.0 - pr / cap) * 40.0;

    // Penalize dead space in already-committed bins: small unusable residue
    // (< smallest plausible item) is wasted capacity.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic classes: post_residual modulo {10, 20, 25, 50} — residues
    // that tile nicely into future item sizes are attractive.
    let mut harmonic_bonus = 0.0;
    for m in [10u32, 20, 25, 50] {
        let r = post_residual % m;
        if r == 0 && post_residual > 0 {
            harmonic_bonus += 12.0;
        } else if r <= 2 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly prefer this bin (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot follow here; slight penalty proportional to waste
            score += 4.0;
        }
    }

    // Prefer filling fuller bins (best-fit bias) more when many bins are open.
    score -= fill_frac * (10.0 + open_bins_count as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when stream is early
        // or many bins are open (parallelism can help later packing).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0 - 20.0 * progress + 0.5 * open_bins_count as f64;
        // Large items leave flexible residue; slightly encourage new bins for them.
        if item_size >= 50 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    // Mean-residual coupling: when average residual is low, conserve bins
    // (pack tighter); when high, tolerate spreading.
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range,
    // assume ~10 as a practical floor) or if it cannot fit the lookahead item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Perfect fill is great (post_residual == 0), tiny gap 1..9 is dead space.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // If the lookahead item cannot fit into the post-residual, this placement
    // likely creates a stranded gap -> penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward when this placement still accommodates the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins mildly unattractive so they are only chosen
    // when no open bin gives a decent fit. Tight fits in existing bins beat new bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening new bins is even less desirable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    // Prefer tighter fits overall: reward small post_residual relative to item size.
    score -= (item_size as f64) / (1.0 + post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when next item fits exactly into post_residual (perfect 2-step chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let waste_after_next = post_residual - next_item_size;
            // penalize leftover dead space after the lookahead item
            score += waste_after_next as f64 * 0.6;
            // bonus if the chain leaves a "useful" residual (>= typical small item)
            if waste_after_next >= 10 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer bins whose residual is tight relative to mean residual (good fit)
    let fit_tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += fit_tightness * 0.25;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless residual is very tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_fit = open_bins_count > 0 && post_residual as f64 <= 15.0;
        if decent_fit {
            score += 25.0; // keep using the well-filled open bin
        } else {
            score += 5.0 - 3.0 * progress; // new bins slightly more acceptable early on
        }
    }

    // Small bonus for filling bins very completely
    if post_residual <= 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Penalize dead space that no plausible item can use (items >= 1, but
    // typical items are large; residual < next_item_size lookahead waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward bins whose leftover can host the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: default slightly worse than a decent fit,
    // but attractive when open bins would leave huge waste or when
    // the stream is early and we want to preserve flexibility.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on: opening bins is cheap, keep large residuals around.
        score += 90.0 * (1.0 - progress) + 30.0;
        // If existing fit is very poor (huge post_residual), new bin wins.
        if post_residual_of_best_is_poor_proxy(post_residual, item_size) {
            score -= 0.0; // handled below via item-size coupling
        }
        // If the item is large, opening fresh bins is more valuable.
        score -= 0.4 * item_size as f64;
    } else {
        // Prefer fuller bins among open bins (best-fit flavor).
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Crowding: many open bins -> consolidate into existing ones.
    if open_bins_count > 4 {
        score += if is_new_bin { 15.0 * open_bins_count as f64 } else { -5.0 };
    }

    // Late stream: squeeze everything into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && !is_new_bin {
        score -= 20.0 * progress;
    }
    if progress > 0.8 && is_new_bin {
        score += 120.0 * progress;
    }

    score
}

#[inline]
fn post_residual_of_best_is_poor_proxy(_post_residual: u32, _item_size: u32) -> bool {
    false
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); late, tolerate residuals
    // that leave room for future items, so weight flips smoothly.
    let prn = pr / cap; // normalized post-residual in [0,1]
    let w_tight = 1.0 - progress;      // weight favoring tight packing early
    let w_room = progress;             // weight favoring usable slack later
    score += w_tight * 12.0 * prn * prn;
    score -= w_room * 6.0 * prn * (1.0 - prn) * (1.0 - prn);

    // Smooth interaction: item_size vs bin_residual fill fraction.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill * (1.0 - progress);

    // Lookahead: reward post_residual that can host next item (smooth kernel).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let k = (diff / 10.0) * (diff / 10.0);
        score -= 10.0 * (-k) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it (smooth sigmoid-like term).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins far from mean residual (fragmentation signal), scaled by openness.
    let dev = (pr - mean_residual) / cap;
    score += open_bins_count as f64 * dev * dev * 4.0;

    // Slight preference for new empty bin when many open bins exist late.
    if bin_residual == bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify the post-residual into modulo-10 residue classes.
    // Residues that are "harmonically useful" (multiples of 10, and small classes
    // that many future items can land in) are rewarded; awkward residues penalized.
    let post = post_residual as i64;
    let residue = (post % 10) as i64;

    // Perfect-fit class: post_residual == 0 is ideal.
    if post == 0 {
        score -= 200.0;
    } else {
        // Reward post-residuals that are multiples of 10 (harmonic with typical sizes).
        if residue == 0 {
            score -= 12.0;
        } else if residue <= 3 || residue >= 8 {
            // Dead-space-like residues: very small or very slanted leftovers.
            score += 8.0;
        }
        // Penalize tiny unusable leftovers more strongly in absolute terms.
        if post < 10 {
            score += 15.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt <= post {
            // Next item fits: big reward, stronger if fit is tight (low slack).
            let slack = post - nxt;
            score -= 25.0;
            if slack < 5 {
                score -= 15.0;
            }
            // Extra reward if next item's size is harmonically aligned (same mod class).
            if (post % 10) == (nxt % 10) {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: mild penalty for stranding the bin.
            score += 6.0;
        }
    }

    // Last-chance logic: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin is a
    // decent fit or when the stream is early and future capacity is valuable.
    if bin_residual == bin_capacity {
        // Base handicap so open bins are usually preferred.
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, opening new bins is wasteful.
        score += 0.15 * open_bins_count as f64;
        if mean_residual > (item_size as f64) * 1.5 {
            score += 25.0;
        }
        // If the only alternative is a single poor-fitting bin, allow new bin.
        if fitting_bins_count == 1 && bin_residual > 0 {
            score -= 0.0; // keep handicap; last-chance bonus above handles open bin
        }
    }

    // Slight preference for filling bins that are already partially used heavily.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Mean-residual harmony: prefer bins close to the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (compaction driver).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score -= 100.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        score -= 6.0;
    }

    // Lookahead: reward if leftover can host the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
