    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Compaction driver: aggressive reward for tight fits, calibrated ladder.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 5 {
        score -= 280.0;
    } else if post_residual < 10 {
        score -= 90.0;
    } else if post_residual < 20 {
        score += 22.0;
    } else if post_residual < 35 {
        score += 7.0;
    } else {
        score -= 6.0;
    }

    // Lookahead: reward leftovers that host the next item, scaled by gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 400.0;
        } else {
            score -= 95.0 * (1.0 - gap as f64 / 55.0).max(0.0);
        }
        if fitting_bins_count <= 2 {
            score -= 35.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead leftover for next item: penalize proportionally.
        score += 0.35 * post_residual as f64;
    }

    // Non-linear coupling: penalize sliver leftovers after tight fits.
    if bin_residual > 0 && post_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.8 && post_residual < 15 {
            score += 12.0 * (fill_ratio - 0.8);
        }
    }

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 260.0;
    }

    // Open-bin pressure: consolidate toward tighter bins as stream progresses.
    if bin_residual as f64 > mean_residual {
        score += 5.0 * pressure;
    } else {
        score -= 3.0 * pressure;
    }

    // New-bin candidate: calibrated opening cost with lookahead coupling.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        let next_large = (next_item_size as f64 / bin_capacity as f64).min(1.0);
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            let penalty = 60.0
                + 150.0 * fragmentation
                - 125.0 * large_item
                + 38.0 * (open_bins_count as f64).ln().max(0.0)
                - 35.0 * progress
                - 50.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation);
            score += penalty.max(0.0);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.4 + 0.25 * progress);
    }

    score
}

