            } else if proxy_post > 9.0 && proxy_post < 15.0 {
                20.0
            } else {
                -10.0 // existing bins fit fine, keep using them
            }
        };
        score = 100.0 - dead_space_pressure - 0.4 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let w_tight = 1.0 - progress;
    let w_room = progress;
    score += w_tight * 12.0 * prn * prn;
    score -= w_room * 6.0 * prn * (1.0 - prn) * (1.0 - prn);

    // Tiered compaction rewards (borrowed, retuned).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual <= 8 {
        score -= 110.0;
    } else if post_residual < 16 {
        score += 20.0;
    } else if post_residual < 30 {
        score += 6.0;
    } else {
        score -= 12.0;
    }

    // Smooth interaction: item_size vs bin_residual fill fraction.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill * (1.0 - progress);

    // Lookahead: reward post_residual that can host next item (tiered gaps).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 450.0;
        } else if gap <= 5 {
            score -= 150.0 * (1.0 - gap as f64 / 6.0);
        } else {
            score -= 100.0 * (1.0 - gap as f64 / 50.0).max(0.0);
        }
        if fitting_bins_count <= 2 {
            score -= 45.0;
        }
        let nl = next_item_size as f64 / cap;
        if nl > 0.5 {
            score -= 30.0 * nl;
        }
        if gap >= next_item_size {
            score -= 22.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let deadness = if pr < 10.0 { 1.35 } else { 1.0 };
        score += pr * (0.38 + 0.3 * (1.0 - progress)) * deadness;
    }

    // Dead-space ratio term with usable-band kernel.
    if bin_residual > 0 && post_residual > 0 {
        if fill > 0.72 && post_residual < 14 {
            score += 18.0 * (fill - 0.72);
        }
        if post_residual < 5 {
            score -= 24.0;
        }
        let res_frac = pr / cap;
        let usable_band = (res_frac * 4.0).sin().abs();
        score -= 14.0 * usable_band * (1.0 - progress * 0.45) * (0.7 + 0.3 * pressure.min(2.0));
        if pr >= 10.0 && pr <= 20.0 {
            score += 9.0 * (1.0 - (pr - 10.0) / 10.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 280.0;
    }

    // Open-bin pressure: consolidate toward tighter bins as stream progresses.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 4.5 * pressure;
    }

    // New-bin candidate logic: calibrated opening cost with fragmentation coupling.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 32.0;
        } else if fitting_bins_count == 1 {
            score += 55.0 + 120.0 * fragmentation;
        } else {
            let penalty = 66.0
                + 180.0 * fragmentation
                - 160.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 46.0 * progress
                - 62.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 34.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.45 + 0.3 * progress);
    }

    // Penalize bins far from mean residual (fragmentation signal), scaled by openness.
    let dev = (pr - mean_residual) / cap;
    score += open_bins_count as f64 * dev * dev * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the leftover space exactly fits the next item, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Leftover can host the next item: mild reward proportional to tightness.
            let tightness = (post_residual - next_item_size) as f64;
            score -= 200.0 - tightness * 0.5;
        } else {
            // Dead space too small for the next item: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize creating tiny unusable slivers (< 10, minimum item size) more than large gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: bins already below-average residual are precious,
    // prefer placing into bins with above-average residual (larger holes).
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Prefer filling bins when many bins are open (reduce bin count pressure).
    score -= (open_bins_count as f64) * (item_size as f64) * 0.05;

    // Early in the stream, opening new bins is cheap; later, prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
