pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fill = item_size as f64 / cap;

    // Base: post residual, with non-linear penalty on mid-range waste
    let mut score = pr * (1.0 + 0.8 * pr_norm * (1.0 - pr_norm) * 4.0);

    // Smooth polynomial coupling with stream progress: early on tolerate waste,
    // later penalize it more strongly (quadratic in progress).
    score *= 0.6 + 0.9 * progress * progress + 0.5 * progress;

    // Reward high fill ratio non-linearly (cubic coupling with progress)
    score -= fill * fill * fill * 30.0 * (0.5 + progress);

    // Perfect fit bonus (smooth exponential decay of residual)
    score -= 25.0 * (-pr * 0.15).exp();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress * 0.5);
    }

    // Penalty for using a bin when many bins fit (prefer spreading across best fits)
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a poor fit
    score += 0.4 * (mean_residual - bin_residual as f64).abs();

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-diff * 0.12).exp();
        // penalize leaving residual too small for the next item
        if pr < next_item_size as f64 {
            score += 0.15 * (next_item_size as f64 - pr);
        }
    }

    // New-bin candidate: prefer it only when open bins would leave large dead space
    if bin_residual == bin_capacity {
        let avg_waste_if_used = mean_residual - item_size as f64;
        let new_bin_score = cap - item_size as f64;
        if avg_waste_if_used > new_bin_score * 1.2 {
            score -= (avg_waste_if_used - new_bin_score) * 1.5;
        } else {
            score += 10.0 + 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
