        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let deadness = if pr < 10.0 { 1.4 } else { 1.0 };
        score += pr * (0.40 + 0.3 * (1.0 - progress)) * deadness;
