        }
        // Penalize residuals too small for typical next items (likely dead space).
        if next_item_size > 0 && pr > 0 && pr < next_item_size as f64 && pr < 12.0 {
            score += 8.0 * (1.0 - pr / 12.0);
        }
    }

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 290.0;
    }

    // Open-bin pressure: consolidate toward tighter bins as stream progresses.
    if bin_residual as f64 > mean_residual {
        score += 7.0 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate logic: calibrated opening cost with fragmentation coupling.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 58.0 + 120.0 * fragmentation;
        } else {
            let penalty = 68.0
                + 180.0 * fragmentation
                - 165.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 48.0 * progress
                - 64.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 35.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.47 + 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit in the leftover space?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainable: reward tighter chains (smaller gap above next item).
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 - gap * 2.0;
        } else {
            // Dead space relative to the next item: penalize proportionally,
            // worst when post_residual is small (unusable sliver).
            let waste = post_residual as f64;
            score += waste * 1.5;
        }
    }

    // Compare against mean residual of open bins: prefer bins that are
    // already more "broken in" (below mean residual) to consolidate fill.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.8;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Encourage consolidation when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 5.0;

    // Slight preference for opening new bins early in the stream when the
    // current bin would be left very fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 150.0 * (1.0 - progress);
    }

    // New-bin candidate baseline: an empty bin gets a neutral-ish score so
    // it only wins when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        score = 250.0 - (next_item_size as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
