pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize small unusable slivers (dead space below the minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fill
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Penalize new bins generally; reduce penalty if item is huge or
        // existing bins are already tight (little usable space left).
        let mut new_bin_penalty = 10.0 + 6.0 * progress;
        if item_size >= 60 && mean_residual < item_size as f64 {
            new_bin_penalty -= 8.0;
        }
        new_bin_penalty -= 4.0 * tightness;
        score += new_bin_penalty.max(0.0);
    }

    // Lookahead: penalize leaving a residual that cannot host the next item,
    // reward residuals that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Global state coupling: with many open bins, discourage waste to avoid
    // bin proliferation; with few bins, be more permissive.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.5 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mild time-horizon term: late in the stream, prioritize exact closure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * fit_ratio;

    score
}

