pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Perfect / near-perfect fit ladder.
    if post_residual == 0 {
        score -= 950.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual <= 8 {
        score -= 110.0;
    } else if post_residual < 16 {
        score += 20.0;
    } else if post_residual < 30 {
        score += 6.0;
    } else {
        score -= 12.0;
    }

    // 2-step lookahead: reward leftovers that host the next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 150.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 100.0 * (1.0 - gap as f64 / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
