            }
            // Chain: leftover can host next item twice over.
            if gap >= next_item_size {
                score -= 22.0;
            }
        } else {
            // Dead space too small for next item: penalize harder early.
            let deadness = if pr < 10.0 { 1.35 } else { 1.0 };
            score += (next_item_size - post_residual) as f64 * (0.38 + 0.3 * (1.0 - progress)) * deadness;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Fragmentation slivers: penalize unusable tiny gaps, but reward sub-5 leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }
    if bin_residual > 0 && post_residual > 0 {
        let ir = item_size as f64 / bin_residual.max(1) as f64;
        if ir > 0.72 && post_residual < 14 {
            score += 18.0 * (ir - 0.72);
        }
        if post_residual < 5 {
            score -= 24.0;
        }
        if pr >= 10.0 && pr <= 20.0 {
            score += 9.0 * (1.0 - (pr - 10.0) / 10.0) * (0.6 + 0.4 * (1.0 - progress));
        }
    }

    // Mean-residual comparison: prefer bins with above-average residual.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 4.5 * pressure;
    }

    // New-bin candidate: calibrated opening cost coupled to fragmentation.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
