pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-based dead-space classes
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in {0} are great; tiny residuals 1..3 are near-waste anyway;
    // mid residuals are dead space. Penalize classes that can't host small items.
    match class {
        0 => score -= 5.0,
        1 | 2 | 3 => score -= 1.0, // nearly unusable, so "cheap" waste
        4..=6 => score += 3.0,     // awkward mid dead space
        _ => score += 1.0,
    }

    // Integer-division thresholds: can a typical next item fit?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward proportionally to how snugly
            score -= (next_item_size as f64) * 0.5;
            if next_item_size == pr {
                score -= 50.0; // chain perfect fit
            }
