            score += 5.0;
        }
    } else {
        // last item: prefer tightest bin
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 60.0;
        // If many open bins exist with plenty of mean residual, discourage new bin
        score += mean_residual * 0.3;
        // If item is large relative to capacity, opening a fresh bin is fine
        score -= (item_size as f64) * 0.4;
        // Early stream: slightly cheaper to open bins (will amortize)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Waste fraction penalty (nonlinear): quadratic in wasted fraction
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 20.0;

    // Prefer filling bins that are already relatively full
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used * 10.0;

    // Coupling: if mean residual across bins is high, prioritize consolidation
    score += mean_residual * 0.05;

    score
}

