    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            // This bin's leftover exactly fits the next item: seal the pair.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover can still host the next item; reward tight coupling.
