    // --- Relative-to-mean residual anchoring ---
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        // Favor bins whose post-residual lands near the pack's average residual
        // (keeps residual profile homogeneous, easier future fits).
        score += 6.0 * rel.abs().tanh() - 4.0 * (-rel.abs() * 2.0).exp();
    }

    // --- Last-chance bin: strongly prefer using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
