    if bin_residual == bin_capacity {
        // Only open a new bin if existing bins are badly fragmented
        // (post_residual would be tiny waste, or next item pairs perfectly).
        let good_reason = next_item_size > 0
            && (post_residual == next_item_size || item_size + next_item_size == bin_capacity);
        if !good_reason {
