            if next_item_size - post_residual <= 6 {
                score -= 18.0;
            }
            if pr >= 4.0 && pr <= 12.0 {
                score -= 24.0 * (1.0 - (pr - 4.0) / 8.0) * (0.4 + 0.6 * (1.0 - progress));
