    }

    // Open-bin pressure.
    if bin_residual as f64 > mean_residual {
        score += 6.0 * pressure;
    } else {
        score -= 4.5 * pressure;
    }

    // New-bin candidate logic with fragmentation coupling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 32.0;
        } else if fitting_bins_count == 1 {
            score += 58.0 + 124.0 * fragmentation;
        } else {
            let penalty = 67.0
                + 180.0 * fragmentation
                - 155.0 * large_item
                + 41.0 * (open_bins_count as f64).ln().max(0.0)
                - 45.0 * progress
                - 62.0 * next_large * (1.0 - progress)
                + 23.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 34.0 * progress * fragmentation;
