        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.46 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.03 * (0.5 + progress);

    // Mutation: mid-residual fragmentation penalty for (16,30) slack band.
