    if post_residual > 0 && post_residual < 10 {
        score += 124.0;
    }
    if post_residual > 0 && post_residual < 5 {
        score -= 26.0;
    }
    if progress > 0.35 && post_residual > 0 && post_residual < 4 {
        score += 42.0 * (1.0 - progress);
    }

    // Non-linear coupling of post_residual with progress.
    let prn = pr / cap;
    let w_tight = 1.0 - progress;
    score += w_tight * 10.0 * prn * prn;
    score -= progress * 5.0 * prn * (1.0 - prn) * (1.0 - prn);

    // Fill interaction.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 7.0 * fill * fill * (1.0 - progress);
    if fill > 0.72 && post_residual < 14 {
        score += 21.0 * (fill - 0.72);
    }
    let waste_ratio = pr / (bin_residual as f64).max(1.0);
    if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
        score += 38.0 * (0.35 - waste_ratio) * (1.2 - progress);
    }
    if waste_ratio < 0.6 && bin_residual as f64 > 0.85 * cap {
        score += 17.0 * (0.6 - waste_ratio) * (0.5 + progress);
    }

    // Two-step lookahead: reward leftovers hosting the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr == n {
            score -= 500.0;
        } else if pr >= n {
            let gap = (pr - n) as u32;
            if gap <= 5 {
                score -= 160.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 105.0 * ((1.0 - gap as f64 / 50.0).max(0.0));
            }
            if fitting_bins_count <= 2 {
                score -= 48.0;
            }
            if gap >= next_item_size {
                score -= 28.0;
            }
            if gap >= (next_item_size / 2) && progress > 0.4 {
                score -= 13.0 * progress;
            }
            if pr >= 2.0 * n {
                score -= 21.0 * (1.0 - progress);
            }
            if pr >= 2 * next_item_size + 1 && progress > 0.25 {
                score -= 10.0 * progress;
            }
            if pr >= 3.0 * n && progress < 0.5 {
                score -= 15.0 * (1.0 - progress);
            }
            if pr >= 25.0 && pr <= 45.0 && n <= 25.0 {
                score -= 11.0 * (1.0 - (pr - 25.0) / 20.0) * (0.4 + 0.6 * progress);
            }
            if pr == (2 * next_item_size) as f64 {
                score -= 32.0;
