    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Tightened fit ladder with sharper near-exact rewards.
    if post_residual == 0 {
        score -= 985.0;
    } else if post_residual <= 2 {
        score -= 340.0;
    } else if post_residual <= 8 {
        score -= 124.0;
    } else if post_residual < 16 {
        score += 24.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 16.0;
    }

    // 2-step lookahead: reward leftovers that host the next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 520.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 172.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 115.0 * (1.0 - gap as f64 / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
                score -= 52.0;
            }
            if gap >= next_item_size {
                score -= 32.0;
