            score -= 28.0;
        }
        if pr >= 10.0 && pr <= 20.0 {
            score += 10.0 * (1.0 - (pr - 10.0) / 10.0) * (0.6 + 0.4 * (1.0 - progress));
        }
        if pr > 10.0 && pr <= 25.0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0 * (1.0 - (pr - 10.0) / 15.0);
        }
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 40.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
        if waste_ratio < 0.6 && bin_residual as f64 > 0.85 * cap {
            score += 18.0 * (0.6 - waste_ratio) * (0.5 + progress);
        }
        if progress > 0.35 && post_residual > 0 && post_residual < 4 {
            score += 44.0 * (1.0 - progress);
        }
        if pr >= 20.0 && pr <= 50.0 {
            score -= 9.0 * (1.0 - (pr - 20.0) / 30.0) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && pr == (2 * next_item_size) as f64 {
            score -= 34.0;
        }
        // Mid-band mop-up bins: leftovers absorbing typical small items.
        if pr >= 25.0 && pr <= 45.0 && next_item_size > 0 && next_item_size <= 25 {
            score -= 12.0 * (1.0 - (pr - 25.0) / 20.0) * (0.4 + 0.6 * progress);
        }
        // Late-stream, prefer bins whose post-residual still absorbs the
        // average small item (<= 20) to keep dead space low.
        if progress > 0.6 && next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
            score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);
        }
        // Dead-space ratio control: bins whose post-residual exceeds a
        // quarter of capacity late in the stream carry forward waste;
        // sharpen the ramp so the chooser is pushed toward tighter bins.
        if progress > 0.45 && pr > 0.25 * cap {
            score += 18.0 * ((pr / cap) - 0.25) * progress;
        }
        // Very late (progress > 0.75), any residual above ~15% of
        // capacity that cannot host the next item is effectively dead —
        // apply a focused penalty to steer selection toward usable space.
        if progress > 0.75 && pr > 0.15 * cap && next_item_size > 0 && post_residual < next_item_size {
            score += 24.0 * ((pr / cap) - 0.15) * (progress - 0.75) * 4.0;
        }
        // Continuous dead-gap penalty — residual that cannot host the next
        // item is penalized proportionally to how much of the next item's
        // demand goes unmet, weighted by stream progress.
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.0 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
        // Reward residuals whose leftover after hosting the next item is
        // itself a common small-item size (<= 10), keeping the chain going
        // beyond the 2-step lookahead.
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 12.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        // NEW (gen 25): endgame sweep — in the final stretch, any residual
        // that cannot host the next item is nearly guaranteed waste; apply
        // a steep ramp so the chooser drains usable space first.
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 30.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        // NEW (gen 25): residual that hosts the next item exactly twice is
        // an ideal mop-up shape; sharpen the discrete reward into a band.
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 16.0 * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 4.5 * pressure;
    }

    // New-bin candidate: only attractive when forced or the item is large
    // and existing fits are poor; otherwise resist opening fresh bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 60.0 + 128.0 * fragmentation;
        } else {
            let penalty = 68.0
                + 185.0 * fragmentation
                - 165.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 48.0 * progress
                - 64.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 36.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 255.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 92.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 70.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 26.0 * (1.0 - post_residual as f64 / cap);
        }
        // Resist fresh bins late when an existing bin leaves a small
        // fillable sliver (<= 12) that later small items can mop up.
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 34.0 * (1.0 - pr / 13.0);
        }
        // Resist fresh bins mid-stream when a mid-band residual remains.
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 20.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        // Resist fresh bins when the residual band 24..=40 can still host
        // the next item, reducing dead-space accumulation mid-stream.
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 16.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
