        // available residual, opening a fresh bin is pure waste — scale
        // resistance with how many alternatives exist.
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        // Late stream, a fresh bin wastes nearly a full empty slot
        // unless the item is large; strengthen resistance proportionally
        // to remaining stream length.
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 26.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        // Fresh-bin resistance scaled by how much dead space would be left
        // behind in the best existing fit — the larger the unmet portion of
        // the next item, the more a fresh bin is wasted.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 14.0 * (unmet / cap) * (0.5 + progress);
        }
        // NEW (gen 25): endgame fresh-bin wall — in the last 10% of the
        // stream, opening a fresh bin almost always wastes it unless the
        // item is huge; resist hard.
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 55.0 * (1.0 - item_size as f64 / 71.0);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.48 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.032 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
