                score += 12.0 * (1.0 - progress);
            }
            // Pairable-size residuals in 1..=6 are easily absorbed later;
            // large misses in 11..=18 are not — penalize harder late.
            if miss > 10 && miss <= 18 && progress > 0.4 {
