            score += 40.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
        if waste_ratio < 0.6 && bin_residual as f64 > 0.85 * cap {
            score += 18.0 * (0.6 - waste_ratio) * (0.5 + progress);
        }
        if progress > 0.35 && post_residual > 0 && post_residual < 4 {
            score += 44.0 * (1.0 - progress);
        }
        if pr >= 20.0 && pr <= 50.0 {
            score -= 9.0 * (1.0 - (pr - 20.0) / 30.0) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && pr == (2 * next_item_size) as f64 {
            score -= 34.0;
        }
        if pr >= 25.0 && pr <= 45.0 && next_item_size > 0 && next_item_size <= 25 {
            score -= 12.0 * (1.0 - (pr - 25.0) / 20.0) * (0.4 + 0.6 * progress);
        }
        if progress > 0.6 && next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
            score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);
        }
        if progress > 0.45 && pr > 0.25 * cap {
            score += 18.0 * ((pr / cap) - 0.25) * progress;
        }
        if progress > 0.75 && pr > 0.15 * cap && next_item_size > 0 && post_residual < next_item_size {
            score += 24.0 * ((pr / cap) - 0.15) * (progress - 0.75) * 4.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.0 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 12.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 30.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 16.0 * (0.5 + 0.5 * progress);
        }
        // GEN 25: quadratic dead-space squeeze — penalize post-residuals
        // exceeding the mean residual, growing quadratically in progress.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.55 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // GEN 25: harvestable-space bonus — residual in 15..=55 band that
        // can host the next item is prime consolidation space.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 16.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 4.5 * pressure;
    }

    // New-bin candidate: only attractive when forced or the item is large
    // and existing fits are poor; otherwise resist opening fresh bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 60.0 + 128.0 * fragmentation;
        } else {
            let penalty = 68.0
                + 185.0 * fragmentation
                - 165.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 48.0 * progress
                - 64.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 36.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 255.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 92.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 70.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 26.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 34.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 20.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 16.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 26.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 14.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 55.0 * (1.0 - item_size as f64 / 71.0);
        }
        // GEN 25: fresh-bin resistance tied to harvestable space — an
        // existing bin's post-fit residual in 15..=45 is still fillable.
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 22.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.48 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.032 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Tightened fit ladder: strong rewards for exact and near-exact fits,
    // calibrated penalties for slivers. Sliver band widened to <=4.
    if post_residual == 0 {
        score -= 970.0;
    } else if post_residual <= 2 {
        score -= 330.0;
    } else if post_residual <= 8 {
        score -= 118.0;
    } else if post_residual < 16 {
        score += 22.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 14.0;
    }

    // 2-step lookahead: reward leftovers that host the next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 165.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 110.0 * (1.0 - gap as f64 / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
                score -= 50.0;
            }
            if gap >= next_item_size {
                score -= 30.0;
            }
            if gap >= (next_item_size / 2) && progress > 0.4 {
                score -= 14.0 * progress;
            }
            if gap > 0 && post_residual >= 2 * next_item_size {
                score -= 22.0 * (1.0 - progress);
            }
            if post_residual >= 3 * next_item_size && progress < 0.5 {
                score -= 16.0 * (1.0 - progress);
            }
            if post_residual >= 2 * next_item_size + 1 && progress > 0.25 {
                score -= 10.0 * progress;
            }
            if gap >= 12 && gap <= 30 && progress > 0.3 {
                score -= 14.0 * progress * (1.0 - gap as f64 / 31.0);
            }
            if gap >= 1 && gap <= 4 && progress > 0.2 {
                score -= 26.0 * (1.0 - gap as f64 / 5.0) * progress;
            }
            if post_residual >= 3 * next_item_size && progress > 0.3 {
                score -= 9.0 * progress;
            }
            // Smooth chain-fit gradient — tighter leftover after hosting
            // the next item is better, boosted by scarcity of alternatives.
            if gap > 0 {
                let tightness = 1.0 - gap as f64 / (cap - next_item_size as f64).max(1.0);
                score -= 20.0 * tightness * (0.4 + 0.6 * progress)
                    / (fitting_bins_count.max(1) as f64).sqrt();
            }
        } else {
            let waste_frac = (next_item_size - post_residual) as f64 / cap;
            let deadness = if pr < 10.0 { 1.45 } else { 1.1 };
            score += (next_item_size - post_residual) as f64 * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 245.0 * waste_frac * (1.0 - progress);
            if next_item_size - post_residual <= 6 {
                score -= 18.0;
            }
            if pr >= 4.0 && pr <= 12.0 {
                score -= 26.0 * (1.0 - (pr - 4.0) / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 20.0 * (1.0 - miss as f64 / 11.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            if miss > 0 && miss <= 3 {
                score += 12.0 * (1.0 - progress);
            }
            if miss > 10 && miss <= 18 && progress > 0.4 {
                score += 12.0 * progress;
            }
            // GEN 25: near-miss salvage — a small miss (<= 15) late in the
            // stream may still be absorbed by other bins; soften the penalty.
            if miss > 0 && miss <= 15 && progress > 0.35 {
                score -= 10.0 * (1.0 - miss as f64 / 16.0) * progress;
            }
            // Near-miss severity ramp — penalize proportionally to miss/cap
            // weighted by scarcity of alternatives.
            if miss > 0 {
                let scarcity = 1.0 + 1.5 / (fitting_bins_count.max(1) as f64);
                score += 30.0 * (miss as f64 / cap) * (0.6 + 0.8 * progress) * scarcity;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 305.0;
    }

    // Fragmentation slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 128.0;
    }
    if bin_residual > 0 && post_residual > 0 {
        let ir = item_size as f64 / bin_residual.max(1) as f64;
        if ir > 0.72 && post_residual < 14 {
            score += 22.0 * (ir - 0.72);
