        // item is penalized proportionally to unmet demand.
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.0 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
