        }
        // GEN 26: mean-residual anchoring — residuals close to the mean are
        // healthy; residuals far below mean are near-dead slivers.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 7.0 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 4.8 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 60.0 + 132.0 * fragmentation;
        } else {
            let penalty = 70.0
                + 190.0 * fragmentation
                - 168.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 50.0 * progress
                - 64.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
