        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 14.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 32.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Quadratic dead-space squeeze above mean residual (GEN 29: steeper, earlier).
        if pr > mean_residual + 6.0 {
            let excess = pr - mean_residual - 6.0;
            score += 0.85 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Harvestable-space bonus: 15..=55 band hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 21.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 12.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty — bins whose post residual exceeds a growing
        // fraction of capacity are poor targets mid-to-late stream (tightened).
        let dead_frac = pr / cap;
        if dead_frac > 0.25 && progress > 0.25 {
