        if progress > 0.5 && next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if leftover <= 8 {
                score -= 22.0 * (1.0 - leftover as f64 / 9.0) * (progress - 0.5) * 2.0;
            }
