            if miss > 0 && miss <= 3 {
                score += 12.0 * (1.0 - progress);
            }
            if miss > 10 && miss <= 18 && progress > 0.4 {
                score += 12.0 * progress;
            }
            if miss > 0 && miss <= 15 && progress > 0.35 {
                score -= 10.0 * (1.0 - miss as f64 / 16.0) * progress;
            }
            // Near-miss severity ramp with scarcity weighting.
            if miss > 0 {
                let scarcity = 1.0 + 1.55 / (fitting_bins_count.max(1) as f64);
                score += 31.0 * (miss as f64 / cap) * (0.6 + 0.8 * progress) * scarcity;
            }
