    } else if post_residual <= 5 {
        score -= 158.0;
    } else if post_residual <= 8 {
        score -= 118.0;
    } else if post_residual < 16 {
        score += 26.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 18.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 530.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 185.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap as f64 / 50.0).max(0.0);
            }
            if gap >= next_item_size {
