    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Tightened fit ladder: deepen exact/near-exact rewards, sharpen sliver penalty.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 360.0;
    } else if post_residual <= 5 {
        score -= 158.0;
    } else if post_residual <= 8 {
        score -= 118.0;
    } else if post_residual < 16 {
        score += 26.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 18.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 530.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 185.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap as f64 / 50.0).max(0.0);
