pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight-fit ladder: deep rewards for exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 360.0;
    } else if post_residual <= 5 {
        score -= 158.0;
    } else if post_residual <= 8 {
        score -= 118.0;
    } else if post_residual < 16 {
        score += 26.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 18.0;
    }

    // Lookahead: reward post_residual hosting next item with chain-fit gradient.
    if next_item_size > 0 {
        if pr == next_item_size as f64 {
            score -= 530.0;
        } else if pr >= next_item_size as f64 {
            let gap = pr - next_item_size as f64;
            if gap <= 5.0 {
                score -= 185.0 * (1.0 - gap / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
                score -= 58.0;
            }
            if gap >= next_item_size as f64 {
                score -= 34.0;
            }
            // Chain-fit gradient: tighter leftover after hosting next item.
            if gap > 0.0 {
                let tightness = 1.0 - gap / (cap - next_item_size as f64).max(1.0);
                score -= 24.0 * tightness * (0.4 + 0.6 * progress)
                    / (fitting_bins_count.max(1) as f64).sqrt();
            }
            // Perfect two-chain: residual exactly 2x next item.
            if pr as u64 == 2 * next_item_size as u64 {
                score -= 42.0 * (0.5 + 0.5 * progress);
            }
            if pr >= 2.0 * next_item_size as f64
                && pr < 3.0 * next_item_size as f64
                && progress > 0.25 {
                score -= 16.0 * (1.0 - progress) * (1.0 - pr / cap);
            }
        } else {
            // Near-miss severity ramp with scarcity weighting.
            let miss = next_item_size as f64 - pr;
            let waste_frac = miss / cap;
            let deadness = if pr < 10.0 { 1.5 } else { 1.1 };
            score += miss * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 255.0 * waste_frac * (1.0 - progress);
            let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
            score += 33.0 * (miss / cap) * (0.6 + 0.8 * progress) * scarcity;
            if miss > 0.0 && miss <= 15.0 && progress > 0.35 {
                score -= 11.0 * (1.0 - miss / 16.0) * progress;
            }
        }
    }

