            score += 6.5 * pressure;
        } else {
            score -= 5.0 * pressure;
        }
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild penalty on large residuals -> prefer tight fits.
    // Late (progress ~ 1): large residuals become less costly (bins close anyway),
    // so the quadratic term decays with progress.
    let decay = 1.0 - progress * progress;
    score += decay * 40.0 * norm_pr * norm_pr * cap;

    // Cubic smooth term: small residuals get a bonus (tight packing), scaled by progress.
    score -= (1.0 - norm_pr).powi(3) * 15.0 * (0.5 + progress);

    // Lookahead: reward residual that can host the next item smoothly (sigmoid-like).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_margin = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 12.0 * fit_margin * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless
    // current residuals are large relative to mean residual.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * progress + 0.05 * mean_residual;
    }

    // Mild coupling with number of open bins: many open bins -> prefer filling them.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    score
}

