    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual (mod 10): dead space quantization
    // Residuals < 10 are unusable for any item -> strong penalty (wasted space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver is worse than it looks
    }

    // Classify post_residual by integer-division thresholds (harmonic bins of 20)
    let class = post_residual / 20; // 0..=5
    // Reward keeping residual in "useful" classes aligned with typical item sizes
    // A residual that can still fit a mid-size item (>= 40) is valuable
    if post_residual >= 40 {
        score -= 6.0 + 0.1 * (class as f64);
    } else if post_residual >= 20 {
        score -= 2.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }
    // If next item exactly fills post_residual, big reward (chained perfect fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If next item does NOT fit and post_residual is small, penalize (dead end)
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it mildly unattractive unless open bins are bad
    if bin_residual == bin_capacity {
        // neutral base = cap; adjust by stream progress and congestion
        score = cap - 5.0
            + 0.05 * (open_bins_count as f64)
            - 10.0 * (1.0 - mean_residual / cap).max(0.0);
        // early stream: opening bins is fine; late stream: prefer filling
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
        // if next item is huge, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Prefer bins tighter than average (filling fullest bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    // Modulo coupling: penalize residuals that are awkward mod classes (e.g. 11..19)
    let awkward = post_residual % 10;
    if post_residual > 0 && awkward >= 1 && post_residual < 30 {
        score += 0.3 * awkward as f64;
    }

    score
}

