        }
        // GEN 30: absolute dead-space tax scaled by item fill density —
        // penalize bins that would remain mostly empty after placement.
        if progress > 0.5 && dead_frac > 0.2 {
            score += 14.0 * (dead_frac - 0.2) * (1.0 - item_size as f64 / cap);
