        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // GEN 30: stronger fresh-bin resistance when an existing bin's post-fit
        // residual stays tight (<= 10) — compaction beats expansion there.
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 10.0 {
            score += 26.0 * (1.0 - pr / 11.0) * (0.3 + 0.7 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (1..100) can use
    // are the worst outcome; a gap below the next item's size is also suspect.
    if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable micro-gap (items >= 1 can use it, but keep mild penalty).
        score += 5.0;
    } else if post_residual < next_item_size && next_item_size > 0 {
        // Gap can't host the lookahead item: penalize dead space extra.
        score += 25.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading into many bins when the new-bin
    // candidate is competitive; encourage closing bins out when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, softened when many
        // open bins already exist (consolidation is hopeless) or when this is
        // the only fitting option context demands.
        score = bin_capacity as f64 * 0.55 + 10.0;
        if open_bins_count > 0 && fitting_bins_count == 0 {
            score -= 20.0; // nothing fits elsewhere, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild bonus when it's the last chance to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Penalize leaving large residuals scattered when many bins are open.
        if open_bins_count > 3 {
            score += (post_residual as f64) * (open_bins_count as f64).ln() * 0.15;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Early stream: be pickier about dead space since long horizon remains.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    score
}

