            let band_high = next_item_size as f64 * 2.0;
            if pr >= band_low && pr <= band_high {
                let centering = 1.0 - ((pr - next_item_size as f64).abs() / band_high);
                score -= 13.0 * centering * (0.3 + 0.7 * progress)
                    / (1.0 + 0.4 * (fitting_bins_count.max(1) as f64));
            } else if pr > band_high && pr < 0.45 * cap {
                score += 9.0 * ((pr - band_high) / cap) * (0.4 + 0.6 * progress);
            }
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 96.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // GEN 30: fresh-bin gate — if the current item leaves a residual that
        // exactly matches the next item, opening a fresh bin is a genuine
        // win (perfect chain); otherwise keep resisting harder late.
        if fitting_bins_count >= 1 && next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 40.0 * (1.0 - progress);
            } else if progress > 0.5 {
                score += 14.0 * progress * (1.0 - (mean_residual / cap).clamp(0.0, 1.0));
            }
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste, but weight residual so that near-perfect
    // 2-step matches dominate over merely small residuals.
    score = post_residual as f64 * 1.0;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can still fit the next item: strong reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack.min(50.0); // best when slack is tiny
    }
    // Post residual cannot fit next item: penalize proportionally to how
    // "unusable" the leftover is relative to capacity.
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += dead * 0.5;
    }

    // Reward tight fits of the current item (bin_residual close to item_size).
    let tightness = (bin_residual - item_size) as f64; // == post_residual
    score -= (bin_capacity as f64 - tightness) * 0.01;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Relative to mean residual: bins with below-average residual are "tighter"
    // and should be consumed first (best-fit global coupling).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless it is genuinely
    // attractive (e.g., very few open bins or huge item with no good fit).
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 {
            (item_size as f64 / bin_capacity as f64).powi(2)
        } else {
            1.0
        };
        score += 300.0 - 250.0 * pressure;
        // Early in stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0;
        }
    }

    score
}

