pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * chain_fit;
        } else {
            // Dead space for the next item: penalize proportionally to wasted space.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.15 * waste;
        }
        // If next item exactly matches post-residual, this is a golden pairing.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.2 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Competition pressure: many fitting bins -> prefer the tightest, mildly.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln() * (1.0 - fill_ratio);
    }

    // Global state: penalize contributing to residual sprawl across open bins.
    score += 0.08 * (post_residual as f64 - mean_residual).abs();

    // Time horizon: early in the stream, be more willing to open fresh bins for
    // better long-run structure; late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when the item is large and fit is poor.
        let large_item_bonus = if item_size > 60 { 18.0 } else { 0.0 };
        let poor_fit_penalty = if fitting_bins_count >= 1 && fill_ratio < 0.5 { 22.0 } else { 0.0 };
        score += 10.0 * (1.0 - progress) - large_item_bonus - poor_fit_penalty
            - if next_item_size > 0 && next_item_size >= post_residual.min(bin_capacity) && post_residual == 0 { 0.0 } else { 0.0 };
