        if open_bins_count > 6 && fill_ratio < 0.6 {
            score -= 12.0;
        }
    } else {
        // Existing bins get a mild baseline advantage over new bins.
        score -= 5.0 * progress;
        // Fragmentation guard: leaving tiny un-usable slivers is bad.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    score
}

