            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // MUTATION: resist opening fresh bins when many bins already fit the item —
        // consolidation beats expansion when alternatives exist.
        if fitting_bins_count >= 3 {
            score += 26.0 * ((fitting_bins_count as f64 - 2.0).min(5.0)) * (0.6 + 0.4 * progress);
        }
        // MUTATION: fresh bin is attractive when it would end up nearly full
        // (post_residual small) early in the stream — efficient dense bin.
        if pr <= 3.0 && progress < 0.4 {
            score -= 30.0 * (1.0 - progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity fractions).
    let r = post_residual % 10;
    // Dead-space penalty: residuals that are too small to ever fit min item (1)
    // are fine, but awkward classes (e.g. residue 1..3) are weakly penalized.
    let class_penalty: f64 = match r {
        0 => -4.0,                       // perfectly harmonic residual
        1..=3 => 2.5,                    // awkward sliver
        4..=6 => 0.5,
        _ => -1.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual / 10 tells usable tiers.
    let tier = post_residual / 10;
    score += match tier {
        0 => 6.0,   // nearly dead bin
        1 => 2.0,
        2 => 0.0,
        3 => -1.5,
        _ => -0.5,
    };

    // Lookahead coupling: reward if next item fits into post_residual (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits the bin currently but not after our placement -> mild penalty
        score += 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many open bins exist and mean residual is small, opening is cheaper.
        score -= open_bins_count as f64 * 0.15;
        if mean_residual < 5.0 {
            score -= 8.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 4.0;
        }
    }

    // Progress: later in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 1.0;

    // Slight preference for tighter fills relative to mean residual.
    score += (mean_residual - post_residual as f64) * 0.03;

    score
}

