        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // GEN 31: resist fresh bins when mean residual is small (bins nearly full,
        // good fits likely); allow when fragmentation is high.
        if fitting_bins_count >= 1 && fragmentation < 0.12 {
            score += 40.0 * (0.12 - fragmentation) / 0.12 * (0.4 + 0.6 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are heavily penalized.
    // A residual is "dead" if it cannot fit the next item nor the smallest possible future item.
    let min_future = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    let dead_threshold = min_future.max(1);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Penalize residuals that cannot fit the lookahead item (wasted capacity for k=2).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward using bins that are already fairly full (low residual before placement).
    score += (bin_residual as f64) * 0.15;

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // a new empty bin (bin_residual == bin_capacity) gets a penalty that grows
    // with the number of open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 6.0;
        // But if no open bin fits well (this is the only fitting candidate),
        // soften the penalty so we don't fragment badly.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild stream-position modulation: early on, be more willing to keep options
    // open (slightly penalize very tight fills); later, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Slight preference for bins whose residual is near the mean (balanced usage),
    // which keeps future item options alive.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
