        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // MUTATION: fresh-bin gate by next-item lookahead — if the next item is
        // large and would leave the fresh bin nearly empty, resist opening.
        if fitting_bins_count >= 1 && next_item_size > 0 && next_item_size as f64 > 0.7 * cap {
            score += 30.0 * progress;
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) as f64;
            // perfect chain (post == next) -> huge bonus
            if gap == 0.0 {
                score -= 25.0;
            } else {
                // penalize gaps that are too small for the next item's leftovers
                score -= 8.0 * (1.0 - gap / bin_capacity as f64);
                // penalize leaving residual the next item can't use at all
                if gap < 10.0 {
                    score += 10.0 * (10.0 - gap);
                }
            }
        } else {
            // next item can't use this bin's residual: dead space penalty
            score += 6.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    if mean_residual > 0.0 {
        score += 3.0 * (post_residual as f64 - mean_residual) / mean_residual;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless no decent fit exists
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
        // but allow opening a new bin if the item is huge relative to residuals
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference early in the stream to consolidate
    if total_items > 0 {
        score -= 2.0 * (1.0 - step_index as f64 / total_items as f64);
    }

    score
}

