            && post_residual >= next_item_size + item_size as u32 {
            score += 30.0 * (0.5 + 0.5 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Prefer tight fits: amplify post-residual penalty quadratically for small leftovers.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let tightness = 1.0 - pr / cap;
        score += (1.0 - tightness) * (pr * pr) / cap * 1.5;
    } else {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: slight penalty if this placement strands space.
            let stranded = (post_residual as f64).min(next_item_size as f64);
            score += 0.08 * stranded;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discard low-utility residuals when many bins are open (avoid fragmenting fleet).
    if open_bins_count > 0 {
        let usable = if post_residual >= 10 { 1.0 } else { 0.0 };
        score += (1.0 - usable) * 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early in stream, be pickier about wasting space; later, just pack.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 0.85 + 0.3 * t;

    // New-bin candidate: only attractive when item barely fits anywhere or residuals are large.
    if bin_residual == bin_capacity {
        let avg_gap = (mean_residual - item_size as f64).max(0.0);
        let desperation = if fitting_bins_count == 0 { 0.0 } else { avg_gap / cap };
        score = cap * 0.6 + desperation * 60.0 - t * 15.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    score
}

