    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear coupling of post_residual with progress:
    // early in the stream, favor tight fills less aggressively (bins stay flexible);
    // late in the stream, heavily penalize leftover dead space.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr / cap) * pr * 0.02;

    // Quadratic penalty for very small post-residuals relative to capacity
    let x = pr / cap;
    score += 4.0 * x * x * (1.0 - progress);

    // Reward near-perfect fills smoothly (post_residual close to 0)
    score -= 8.0 * (-pr / 6.0).exp() * (0.5 + progress);

    // Lookahead coupling: if the next item fits smoothly into post_residual, reward it
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 3.0 * (-gap / 10.0).exp();
