    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: make an empty bin moderately attractive, tuned by progress
    if bin_residual == bin_capacity {
        score -= 2.0 + 4.0 * (1.0 - progress) * (mean_residual / cap);
    }

    score
}

