            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // GEN 33: fresh-bin resistance when the best existing fit is already tight
        // (post residual small) — avoid wasting a fresh bin on a nearly-full bin.
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 3.0 {
            score += 30.0 * (1.0 - pr / 4.0) * (0.5 + 0.5 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in "unusable" small gaps is heavily penalized.
    // A residual that cannot plausibly host a future item (below the minimum item size 1..100,
    // assume small items >= 5) is dead space; the smaller the gap, the worse.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0 + (5.0 - post_residual as f64) * 10.0;
    } else if post_residual >= 5 && post_residual < 15 {
        // Risky zone: only tiny items can fill it later.
        score += (15.0 - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fits (small but non-zero post_residual is fine if gap is tiny relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 12.0 * (fill_ratio - 0.9) * 10.0; // up to -12 for perfect fit
    }

    // If this bin's post_residual can exactly host the lookahead item, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Prefer bins whose leftover still accommodates the next item.
        score -= 3.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leftover too small for lookahead: penalize proportionally.
        score += 2.0 + (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 5.0; // nearly full bin anyway, no loss
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets a penalty scaled by open_bins_count.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 1.5;
        // Opening a new bin is acceptable if existing fits would leave large dead space.
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score -= 4.0;
        }
    } else {
        // Mild reward for using existing bins, stronger when many are open.
        score -= (open_bins_count as f64).min(10.0) * 0.4;
    }

    // Prefer bins below mean residual (consolidating space).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Late in the stream, tighten up: avoid leaving any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
