        // fraction of capacity are poor targets mid-to-late stream.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        // GEN 33: sharper dead-space penalty in the late stream — bins left with
        // >40% free space late are the main source of wasted bins.
        if dead_frac > 0.4 && progress > 0.55 {
            score += 46.0 * (dead_frac - 0.4) * (progress - 0.55) * 3.0
                / (fitting_bins_count.max(1) as f64).sqrt();
        }
        // GEN 33: reward bins whose dead space is small but nonzero and matches
        // the mean residual — these are the well-compacted targets.
        if dead_frac > 0.02 && dead_frac < 0.18 && progress > 0.25 {
            score -= 14.0 * (1.0 - dead_frac / 0.18) * (0.4 + 0.6 * progress);
