        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // GEN 33: strongest fresh-bin resistance when the best existing fit
        // leaves only a tiny sliver — never abandon a nearly-perfect bin.
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 3.0 {
            score += 90.0 * (1.0 - pr / 4.0);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual small)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual exactly or nearly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin filled by next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - slack / (bin_capacity as f64)); // good lookahead fit
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // penalize leaving a residual that just barely misses the next item
            score += 12.0 * (gap / (bin_capacity as f64)).min(1.0);
        }
    }

    // Penalize residuals that are too small to ever be useful (dead space)
    if post_residual < 10 {
        score -= 25.0; // nearly-full bin is great, close it out
    } else if post_residual < 25 {
        score += 6.0; // awkward small residual zone
    }

    // Compare against mean residual: prefer bins that become closer to mean after placement
    let post_f = post_residual as f64;
    let dev = (post_f - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // open a fresh bin if open bins are quite full on average
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 15.0;
        }
    }

    // Late in the stream, consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

