        }
        // GEN 34: dead-space floor refinement — bins whose post residual sits
        // just above what the next item would consume are near-perfect targets;
        // reward the narrow band [next, next+6] more aggressively late.
        if next_item_size > 0
            && post_residual >= next_item_size
            && post_residual <= next_item_size + 6
            && progress > 0.3
        {
