        // GEN 34: penalize post residuals in the awkward band just below the
        // next item — space that will almost surely go unused.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let shortfall = (next_item_size - post_residual) as f64;
            if shortfall <= 8 {
                score += 12.0 * (1.0 - shortfall / 9.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 96.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // GEN 28: extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // GEN 34: extra resistance when an existing bin's post residual is a
        // near-perfect match (within 6) for the next item late in the stream.
        if fitting_bins_count >= 1
            && next_item_size > 0
            && post_residual >= next_item_size
            && post_residual <= next_item_size + 6
            && progress > 0.5
        {
            score += 26.0 * progress;
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Reward perfect/near-perfect fills heavily.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size as f64 > post_residual as f64 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        } else {
            score -= 0.15 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    } else {
        // Last item: any residual is pure waste; prefer fullest bin.
        score -= 15.0 * tightness;
    }

    // New-bin candidate handling: opening a bin is expensive early/mid stream,
    // but acceptable late or when the current bin fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if fitting_bins_count > 0 {
            (bin_residual - item_size.min(bin_residual)) as f64 / bin_capacity as f64
        } else {
            1.0
        };
        // New bin penalty decays with progress; grows with existing bin count.
        let mut penalty = 18.0 * (1.0 - 0.5 * progress) + 0.4 * open_bins_count as f64;
        // If the item is large relative to residual in existing bins, new bin is fine.
        penalty -= 6.0 * (item_size as f64 / bin_capacity as f64);
        // If this bin is the only fitting option, opening a new bin is wasteful.
        if fitting_bins_count == 1 {
            penalty += 10.0;
        }
        // If mean residual is high, we should use existing bins instead.
        penalty += 0.08 * mean_residual;
        score += penalty.max(0.0);
    } else {
        // Mild penalty for using bins whose residual is much larger than needed
        // (wasting space that could hold bigger future items).
        let waste = (bin_residual - item_size) as f64;
        if waste > 40.0 && item_size < 30 {
            score += 0.1 * (waste - 40.0);
        }
    }

    // Global state: when many bins are open with high mean residual,
    // encourage consolidation into existing bins.
    if !is_new_bin {
        score -= 0.02 * mean_residual;
    }

    // Time horizon: late in the stream, close out bins (favor tight fits even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
