        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.5 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 14.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 32.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Quadratic dead-space squeeze above mean residual.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.65 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Harvestable-space bonus: 15..=55 band hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 11.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty — bins whose post residual exceeds a growing
        // fraction of capacity are poor targets mid-to-late stream.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        // GEN 35: dead-space-vs-need coupling — penalize large dead space only
        // when the next item cannot use it; reward it when it exactly hosts the
        // next item's chain.
        if dead_frac > 0.2 && next_item_size > 0 {
            if post_residual < next_item_size {
                score += 26.0 * (dead_frac - 0.2) * (0.5 + 0.5 * progress);
            } else if post_residual % next_item_size.max(1) == 0 {
                score -= 14.0 * (dead_frac - 0.2) * (0.4 + 0.6 * progress);
            }
        }
        // GEN 35: residual variance damping — prefer bins whose post residual
        // stays near the global mean residual band when few fitting bins remain.
        if fitting_bins_count <= 3 && pr > 0.0 {
            let band = 10.0 + 10.0 * progress;
            if (pr - mean_residual).abs() > band {
                score += 6.0 * ((pr - mean_residual).abs() - band) / cap
                    * (1.0 + 1.0 / fitting_bins_count.max(1) as f64);
            }
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 96.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // GEN 35: fresh-bin opening is justified when the current item would
        // leave a residual that exactly matches the next item (seeded chain).
        if next_item_size > 0 && post_residual == next_item_size && progress < 0.6 {
            score -= 40.0 * (1.0 - progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: total dead space.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spawning new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well,
    // i.e. when the best existing option would leave a bad gap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the item is large, a fresh bin is a good home.
        if item_size > 60 {
            score -= 45.0;
        }
        // Late in the stream, avoid proliferation.
        if progress > 0.7 {
            score += 15.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward leaving exactly that space; otherwise penalize mismatch.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 4.0;
        }
    }

    // Mean residual coupling: bins far below the mean residual waste capacity
    // elsewhere; prefer bins whose residual is near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Deepened fit ladder: reward exact/near-exact fits, punish slivers.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 360.0;
    } else if post_residual <= 5 {
        score -= 158.0;
    } else if post_residual <= 8 {
        score -= 118.0;
    } else if post_residual < 16 {
        score += 26.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 18.0;
    }

    // Lookahead: chain-fit gradient toward hosting the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 530.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 5.0 {
                score -= 185.0 * (1.0 - gap / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap / 50.0).max(0.0);
            }
            if gap >= next_item_size as f64 {
                score -= 34.0;
            }
            if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
                score -= 42.0 * (0.5 + 0.5 * progress);
            }
            if gap > 0.0 {
                let tightness = 1.0 - gap / (cap - next_item_size as f64).max(1.0);
                score -= 24.0 * tightness * (0.4 + 0.6 * progress)
                    / (fitting_bins_count.max(1) as f64).sqrt();
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            let deadness = if pr < 10.0 { 1.5 } else { 1.1 };
            score += miss * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 255.0 * (miss / cap) * (1.0 - progress);
            if miss <= 3.0 {
                score += 13.0 * (1.0 - progress);
            }
            let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
            score += 33.0 * (miss / cap) * (0.6 + 0.8 * progress) * scarcity;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Fragmentation slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 138.0;
    }
    if bin_residual > 0 && post_residual > 0 {
        let ir = item_size as f64 / bin_residual.max(1) as f64;
        if ir > 0.72 && post_residual < 14 {
            score += 24.0 * (ir - 0.72);
        }
        if post_residual < 5 {
            score -= 32.0;
        }
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 44.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
        // Quadratic dead-space squeeze above mean residual.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.65 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Harvestable-space bonus: 15..=55 band hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress)
                * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Residual-efficiency term.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 11.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty mid-to-late stream.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling: resist opening fresh bins unless forced
    // or the item is huge.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if item_size as f64 > 0.8 * cap {
            score -= 20.0;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // ---- 2-step lookahead: exact match of post_residual with next item is gold ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-item packing: strongly reward.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here; the tighter the fit, the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow; penalize leftover dead space, more so
            // if the leftover is small enough that nothing else will use it.
            let waste = post_residual as f64;
            score += 0.35 * waste;
            if waste < 10.0 {
                score += 8.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item: just prefer tightest fit (smallest post_residual handled by base term).
    }

    // ---- Relative-to-mean-residual coupling ----
    // Bins already tighter than average should be preferred to close them out;
    // loose bins keep capacity for future items.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // ---- Last-chance bonus: only bin that fits -> avoid opening a new bin ----
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // ---- New bin candidate handling ----
    if is_new_bin {
        // Opening a new bin is attractive only when no open bin fits well
        // or the existing fits are poor (large post_residual).
        let best_existing = if fitting_bins_count > 0 {
            // approximate: existing bins leave at least item_size waste elsewhere;
            // use mean_residual as proxy for how full open bins are.
            mean_residual
        } else {
            f64::INFINITY
        };
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Empty bin gives perfect room for lookahead pairing.
            score -= 30.0;
        } else if mean_residual < item_size as f64 {
            // Open bins are nearly full anyway; new bin is fine.
            score -= 5.0;
        } else {
            // Prefer using open bins; penalize new bin moderately.
            score += 15.0 + 0.1 * mean_residual;
        }
        let _ = best_existing;
    }

    // ---- Slight early-stream exploration: keep bins open longer early on ----
    score += 2.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

