}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual becomes tiny but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use leftover space: penalize large leftovers.
            score += 0.15 * post_residual as f64;
        }
    }

    // Time horizon: early on, prefer spreading load (favor new bins slightly);
    // late, consolidate tightly into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline plus openness pressure.
        let mut nb = 30.0;
        nb -= 20.0 * progress;
        // Open fewer bins when many bins already exist relative to items seen.
        if step_index > 0 {
            let density = open_bins_count as f64 / (step_index as f64 + 1.0);
            nb += 40.0 * density;
        }
        // If current item nearly fills a fresh bin, new bin is attractive.
        if item_size >= bin_capacity * 9 / 10 {
            nb -= 35.0;
        }
        score = score.max(nb.min(score)) ; // keep at least comparable to existing
        score = score + nb * 0.0; // no-op guard
        score = nb;
    } else {
        // Existing bin: consolidate more aggressively as stream progresses.
        score -= 10.0 * progress;
        // Prefer bins below mean residual (less-packed bins get priority to balance).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Mild global pressure: with many open bins, avoid opening more.
    if bin_residual == bin_capacity && open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

