    } else if post_residual <= 5 {
        score -= 158.0;
    } else if post_residual <= 8 {
        score -= 118.0;
    } else if post_residual < 16 {
        score += 26.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 18.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 530.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 185.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap as f64 / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
                score -= 58.0;
            }
            if gap >= next_item_size {
                score -= 34.0;
            }
            if gap >= (next_item_size / 2) && progress > 0.4 {
                score -= 16.0 * progress;
            }
            if gap > 0 && post_residual >= 2 * next_item_size {
                score -= 26.0 * (1.0 - progress);
            }
            if post_residual >= 3 * next_item_size && progress < 0.5 {
                score -= 19.0 * (1.0 - progress);
            }
            if post_residual >= 2 * next_item_size + 1 && progress > 0.25 {
                score -= 12.0 * progress;
            }
            if gap >= 12 && gap <= 30 && progress > 0.3 {
                score -= 16.0 * progress * (1.0 - gap as f64 / 31.0);
            }
            if gap >= 1 && gap <= 4 && progress > 0.2 {
                score -= 30.0 * (1.0 - gap as f64 / 5.0) * progress;
            }
            if post_residual >= 3 * next_item_size && progress > 0.3 {
                score -= 11.0 * progress;
            }
            // Chain-fit gradient: tighter leftover after hosting next item.
            if gap > 0 {
                let tightness = 1.0 - gap as f64 / (cap - next_item_size as f64).max(1.0);
                score -= 24.0 * tightness * (0.4 + 0.6 * progress)
                    / (fitting_bins_count.max(1) as f64).sqrt();
            }
            // Exact double-fit bonus.
            if post_residual >= 2 * next_item_size
                && post_residual < 3 * next_item_size
                && progress > 0.25 {
                score -= 16.0 * (1.0 - progress) * (1.0 - pr / cap);
            }
            // Perfect two-chain — residual exactly 2x next item is ideal.
            if post_residual as u64 == 2 * next_item_size as u64 {
                score -= 42.0 * (0.5 + 0.5 * progress);
            }
            // Triple-chain lookahead — residual hosting next item twice
            // plus a small remainder is a compounding target.
            if post_residual as u64 >= 3 * next_item_size as u64
                && (post_residual as u64 - 3 * next_item_size as u64) <= 4
                && progress > 0.3 {
                score -= 22.0 * progress;
            }
            // GEN 37: quad-chain lookahead — bins big enough to absorb the
            // next item four times over with tiny remainder are prime
            // consolidation targets; reward early before they fragment.
            if post_residual as u64 >= 4 * next_item_size as u64
                && (post_residual as u64 - 4 * next_item_size as u64) <= 6
                && progress < 0.6 {
                score -= 20.0 * (1.0 - progress);
            }
            // GEN 37: post-chain dead-space quality — the leftover *after*
            // hosting the next item should be either zero-ish or large
            // enough to keep absorbing; penalize the awkward 9..20 band.
            if gap > 0 && gap >= 9 && gap <= 20 && progress > 0.35 {
                score += 12.0 * (gap as f64 - 8.0) / 12.0 * progress;
            }
        } else {
            let waste_frac = (next_item_size - post_residual) as f64 / cap;
            let deadness = if pr < 10.0 { 1.5 } else { 1.1 };
            score += (next_item_size - post_residual) as f64 * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 255.0 * waste_frac * (1.0 - progress);
            if next_item_size - post_residual <= 6 {
                score -= 18.0;
            }
            if pr >= 4.0 && pr <= 12.0 {
                score -= 28.0 * (1.0 - (pr - 4.0) / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 21.0 * (1.0 - miss as f64 / 11.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            if miss > 0 && miss <= 3 {
                score += 13.0 * (1.0 - progress);
            }
            if miss > 10 && miss <= 18 && progress > 0.4 {
                score += 13.0 * progress;
            }
            if miss > 0 && miss <= 15 && progress > 0.35 {
                score -= 11.0 * (1.0 - miss as f64 / 16.0) * progress;
            }
            // Near-miss severity ramp with scarcity weighting.
            if miss > 0 {
                let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
                score += 33.0 * (miss as f64 / cap) * (0.6 + 0.8 * progress) * scarcity;
            }
            // GEN 37: near-miss bins that could host the *following* item
            // after this one gets smaller — soften penalty when the miss is
            // small and the next item is large (this bin likely still wins).
            if miss > 0 && miss <= 5 && next_item_size >= 60 {
                score -= 9.0 * (1.0 - miss as f64 / 6.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Fragmentation slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 138.0;
    }
    if bin_residual > 0 && post_residual > 0 {
        let ir = item_size as f64 / bin_residual.max(1) as f64;
        if ir > 0.72 && post_residual < 14 {
            score += 24.0 * (ir - 0.72);
        }
        if post_residual < 5 {
            score -= 32.0;
        }
        if pr >= 10.0 && pr <= 20.0 {
            score += 10.0 * (1.0 - (pr - 10.0) / 10.0) * (0.6 + 0.4 * (1.0 - progress));
        }
        if pr > 10.0 && pr <= 25.0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (pr - 10.0) / 15.0);
        }
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 44.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
        if waste_ratio < 0.6 && bin_residual as f64 > 0.85 * cap {
            score += 20.0 * (0.6 - waste_ratio) * (0.5 + progress);
        }
        if progress > 0.35 && post_residual > 0 && post_residual < 4 {
            score += 48.0 * (1.0 - progress);
        }
        if pr >= 20.0 && pr <= 50.0 {
            score -= 10.0 * (1.0 - (pr - 20.0) / 30.0) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && pr == (2 * next_item_size) as f64 {
            score -= 38.0;
        }
        if pr >= 25.0 && pr <= 45.0 && next_item_size > 0 && next_item_size <= 25 {
            score -= 14.0 * (1.0 - (pr - 25.0) / 20.0) * (0.4 + 0.6 * progress);
        }
        if progress > 0.6 && next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
            score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);
        }
        if progress > 0.45 && pr > 0.25 * cap {
            score += 20.0 * ((pr / cap) - 0.25) * progress;
        }
        if progress > 0.75 && pr > 0.15 * cap && next_item_size > 0 && post_residual < next_item_size {
            score += 26.0 * ((pr / cap) - 0.15) * (progress - 0.75) * 4.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.5 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 14.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 32.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Quadratic dead-space squeeze above mean residual.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.65 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Harvestable-space bonus: 15..=55 band hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 11.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty — bins whose post residual exceeds
        // a growing fraction of capacity are poor targets mid-to-late stream.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        // Also penalize the 0.12..0.3 band late in the stream when no item
        // can fill it, steering placement toward truly minimal leftovers.
        if dead_frac > 0.12 && dead_frac <= 0.3 && progress > 0.5
            && next_item_size > 0 && post_residual < next_item_size {
            score += 16.0 * (dead_frac - 0.12) * (progress - 0.5) * 3.0;
        }
        // Complement — reward bins whose dead-space fraction stays
        // below 0.1 after placement, scaled by stream progress.
        if dead_frac <= 0.1 && post_residual > 0 {
            score -= 14.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // GEN 37: residual divisibility probe — if the post residual is an
        // exact multiple of the next item size (2x..5x), this bin can be
        // filled perfectly by a chain of upcoming items; reward strongly.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let k = post_residual / next_item_size;
            if k >= 2 && k <= 5 && post_residual % next_item_size == 0 {
                score -= 26.0 * (1.0 - (k as f64 - 2.0) / 4.0) * (0.4 + 0.6 * progress);
            }
        }
        // GEN 37: late-stream micro-fit sweep — when few fitting bins remain,
        // prefer the bin whose post residual best matches the *smallest*
        // plausible future item, keeping doors open instead of stranding.
        if progress > 0.6 && fitting_bins_count <= 3 && post_residual > 0 && post_residual <= 25 {
            score -= 10.0 * (1.0 - post_residual as f64 / 26.0) * (progress - 0.6) * 2.5;
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 96.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // Fresh-bin resistance when existing bins can host the item
        // with near-exact fit (post residual <= 8), preserving those tight fits.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 30.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // GEN 37: fresh-bin resistance when an existing bin is an exact
        // chain container for the next item (residual divisible by it).
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual > 0
            && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score += 22.0 * (0.4 + 0.6 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Tight fit ladder: deep rewards for exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 340.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score -= 110.0;
    } else if post_residual < 16 {
        score += 24.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 16.0;
    }

    // Lookahead: next-item fit quality dominates.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 5.0 {
                score -= 175.0 * (1.0 - gap / 6.0);
            } else {
                score -= 115.0 * (1.0 - gap / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
                score -= 55.0;
            }
            if gap >= next_item_size as f64 {
                score -= 32.0;
            }
            // Chain-fit gradient: tighter leftover after hosting next item.
            let tightness = 1.0 - gap / (cap - next_item_size as f64).max(1.0);
            score -= 22.0 * tightness * (0.4 + 0.6 * progress)
                / (fitting_bins_count.max(1) as f64).sqrt();
            // Perfect two-chain.
            if post_residual as u64 == 2 * next_item_size as u64 {
                score -= 40.0 * (0.5 + 0.5 * progress);
            }
            // Triple-chain lookahead.
            if post_residual as u64 >= 3 * next_item_size as u64
                && (post_residual as u64 - 3 * next_item_size as u64) <= 4
                && progress > 0.3 {
                score -= 20.0 * progress;
            }
            if gap >= 1.0 && gap <= 10.0 && progress > 0.15 {
                score -= 13.0 * (1.0 - gap / 11.0) * (0.5 + 0.5 * progress);
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            let waste_frac = miss / cap;
            let deadness = if pr < 10.0 { 1.5 } else { 1.1 };
            score += miss * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 245.0 * waste_frac * (1.0 - progress);
            if miss <= 3.0 {
                score -= 12.0 * (1.0 - progress);
            }
            if miss <= 10.0 {
                score += 20.0 * (1.0 - miss / 11.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            // Near-miss severity with scarcity weighting.
            let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
            score += 32.0 * (miss / cap) * (0.6 + 0.8 * progress) * scarcity;
        }
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 310.0;
    }

    if bin_residual > 0 && post_residual > 0 {
        // Fragmentation slivers.
        if post_residual < 10 {
            score += 130.0;
        }
        if post_residual < 5 {
            score -= 30.0;
        }
        let ir = item_size as f64 / bin_residual.max(1) as f64;
        if ir > 0.72 && post_residual < 14 {
            score += 24.0 * (ir - 0.72);
        }
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 42.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
        // Residual-efficiency term.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 11.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        if dead_frac <= 0.1 {
            score -= 14.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // Quadratic dead-space squeeze above mean residual.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.65 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Harvestable-space bonus (15..=55 hosting next item).
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress)
                * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
    }

    // Mean-residual comparison / consolidation pressure.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 255.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
