                && (post_residual as u64 - 3 * next_item_size as u64) <= 4
                && progress > 0.3 {
                score -= 22.0 * progress;
            }
            // GEN 38: quad-chain lookahead — residual that can host the next
            // item four times with tiny remainder signals an ideal long-term
            // sink; reward it early-to-mid stream when such bins are rare.
