pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Exact / near-exact fit ladder (borrowed compaction idea, recalibrated).
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 140.0;
    } else if post_residual <= 8 {
        score -= 100.0;
    } else if post_residual < 16 {
        score += 24.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        score -= 14.0;
    }

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap;
    let w_tight = 1.0 - progress;
    let w_room = progress;
    score += w_tight * 10.0 * prn * prn;
    score -= w_room * 5.0 * prn * (1.0 - prn) * (1.0 - prn);

    // Smooth interaction: item_size vs bin_residual fill fraction.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 7.0 * fill * fill * (1.0 - progress);

    // Lookahead: reward post_residual hosting next item, with chain gradient.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 480.0;
        } else if post_residual >= next_item_size {
            let gap = pr - next_item_size as f64;
            if gap <= 5.0 {
                score -= 160.0 * (1.0 - gap / 6.0);
            } else {
                score -= 100.0 * (1.0 - gap / 50.0).max(0.0);
            }
            // Chain-fit tightness: leftover after hosting next item.
            let tightness = 1.0 - gap / (cap - next_item_size as f64).max(1.0);
            score -= 22.0 * tightness * (0.4 + 0.6 * progress)
                / (fitting_bins_count.max(1) as f64).sqrt();
            // Exact double-fit target.
            if post_residual as u64 == 2 * next_item_size as u64 {
                score -= 40.0 * (0.5 + 0.5 * progress);
            }
            // Triple-chain lookahead.
            if post_residual as u64 >= 3 * next_item_size as u64
                && (post_residual as u64 - 3 * next_item_size as u64) <= 4
                && progress > 0.3 {
                score -= 20.0 * progress;
            }
            if fitting_bins_count <= 2 {
                score -= 50.0;
            }
        } else {
            // Near-miss severity ramp with scarcity weighting.
            let miss = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
            score += miss * (0.4 + 0.3 * (1.0 - progress))
                + 240.0 * (miss / cap) * (1.0 - progress);
            score += 30.0 * (miss / cap) * (0.6 + 0.8 * progress) * scarcity;
            if miss <= 3.0 {
                score -= 12.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Fragmentation slivers: penalize tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 110.0;
    }

    // Dead-space squeeze above mean residual.
