    }
    let dev = (pr - mean_residual) / cap;
    score += open_bins_count as f64 * dev * dev * 3.0;

    // Residual-efficiency term.
    let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
    score -= 10.0 * fill_frac * (0.4 + 0.6 * progress)
        * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));

    // Dead-space ratio shaping.
    let dead_frac = pr / cap;
    if dead_frac > 0.3 && progress > 0.3 {
        score += 30.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
    }
    if dead_frac <= 0.1 && post_residual > 0 {
        score -= 12.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling: resist opening fresh bins unless necessary.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count == 1 {
            score += 60.0 + 130.0 * fragmentation;
        } else {
            let penalty = 70.0 + 180.0 * fragmentation - 160.0 * large_item
                + 35.0 * (open_bins_count as f64).ln().max(0.0)
                - 50.0 * progress;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 240.0 * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 8.0 {
            score += 70.0 * (1.0 - pr / 9.0) * (0.4 + 0.6 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 90.0 * (progress - 0.7) * 3.0;
        }
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 18.0;
        }
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 22.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: normalized post-residual, with non-linear (quadratic/cubic) coupling
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = x * (1.0 + 2.0 * x * x);

    // Smooth stream-progress coupling: as stream advances, tighten packing (amplify residual penalty)
    let tighten = 1.0 + 2.5 * progress * progress;
    score *= tighten;

    // Reward tight fits (small post_residual relative to item size) via smooth interaction
    let fit_ratio = it / cap;
    score -= 3.0 * fit_ratio * (1.0 - x) * (1.0 - x);

    // Lookahead: penalize post_residual that cannot fit the next item (dead space), reward exact synergy
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item fits: smooth reward proportional to how well residual is used
            score -= 2.0 * (nx / cap) * (1.0 - (pr - nx) / cap);
        } else {
            // dead space: smooth quadratic penalty on unusable remainder
            let gap = (pr - nx) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 3.0 * progress;
    }

    // Crowding effect: many open bins -> prefer filling existing ones (penalize new-bin tendency)
    let crowd = (open_bins_count as f64).ln_1p();
    score += 0.5 * crowd * x;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * (1.0 - progress);

    // Slight penalty for opening a brand-new bin when open bins exist
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
