    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 96.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // Fresh-bin resistance when existing bins can host the item
        // with near-exact fit (post residual <= 8).
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 30.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // GEN 39: fresh-bin resistance when the item leaves an existing bin
        // with a residual that still hosts the NEXT item (chain preservation).
        if fitting_bins_count >= 1 && next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 6 {
            score += 26.0 * (0.4 + 0.6 * progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item
    // (min item size 1, but practically small gaps) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }
    // Gap too small even for the next item: likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward leaving a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Tightness bonus: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

