        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // Fresh-bin resistance when existing bins can host the item
        // with near-exact fit (post residual <= 8), preserving those tight fits.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 32.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // GEN 41: fresh-bin resistance when an existing bin can host both the
        // current item and the next one with a tight remainder (<= 6).
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            if rem <= 6 {
                score += 26.0 * (1.0 - rem as f64 / 7.0) * (0.5 + 0.5 * progress);
            }
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual is "dead" if no realistic future item (>=1) can ever use it well;
    // treat gaps below a small threshold as wasted capacity.
    let dead_threshold: f64 = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += pressure * 6.0;
        // If a fitting bin exists at all, new bin is less attractive.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    } else {
        // Reward using existing bins more when pressure is high.
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 5 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    }
    // If next item would leave this bin's post-residual dead, slight penalty.
    if next_item_size > post_residual && post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    score
}

