pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_u = post_residual;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tightened fit ladder (borrowed from elite lineage): deep rewards for
    // exact/near-exact fits, sharp sliver penalties, bonus for large leftovers.
    if pr_u == 0 {
        score -= 1000.0;
    } else if pr_u <= 2 {
        score -= 360.0;
    } else if pr_u <= 5 {
        score -= 158.0;
    } else if pr_u <= 8 {
        score -= 118.0;
    } else if pr_u < 16 {
        score += 26.0;
    } else if pr_u < 30 {
        score += 5.0;
    } else {
        score -= 18.0;
    }

    // Coupling with next item: strong lookahead rewards for hosting it.
    if next_item_size > 0 {
        if pr_u == next_item_size {
            score -= 530.0;
        } else if pr_u >= next_item_size {
            let gap = (pr_u - next_item_size) as f64;
            if gap <= 5.0 {
                score -= 185.0 * (1.0 - gap / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
                score -= 58.0;
            }
            if gap >= next_item_size as f64 {
                score -= 34.0;
            }
            if gap >= (next_item_size as f64) / 2.0 && progress > 0.4 {
                score -= 16.0 * progress;
            }
            // Perfect two-chain: residual exactly 2x next item.
            if pr_u as u64 == 2 * next_item_size as u64 {
                score -= 42.0 * (0.5 + 0.5 * progress);
            }
            // Triple-chain lookahead with small remainder.
            if pr_u as u64 >= 3 * next_item_size as u64
                && (pr_u as u64 - 3 * next_item_size as u64) <= 4
                && progress > 0.3 {
                score -= 22.0 * progress;
            }
            // Chain-fit gradient: tighter leftover after hosting next item.
            let tightness = 1.0 - gap / (cap - next_item_size as f64).max(1.0);
            score -= 24.0 * tightness * (0.4 + 0.6 * progress)
                / (fitting_bins_count.max(1) as f64).sqrt();
        } else {
            let miss = (next_item_size - pr_u) as f64;
            let waste_frac = miss / cap;
            let deadness = if pr < 10.0 { 1.5 } else { 1.1 };
            score += miss * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 255.0 * waste_frac * (1.0 - progress);
            if miss <= 6.0 {
                score -= 18.0;
            }
            // Near-miss severity ramp with scarcity weighting.
            let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
            score += 33.0 * (miss / cap) * (0.6 + 0.8 * progress) * scarcity;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Fragmentation slivers and harvestable bands.
    if pr_u > 0 && pr_u < 10 {
        score += 138.0;
    }
    if bin_residual > 0 && pr_u > 0 {
        let ir = item_size as f64 / (bin_residual.max(1) as f64);
        if ir > 0.72 && pr_u < 14 {
            score += 24.0 * (ir - 0.72);
        }
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 44.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
        // Quadratic dead-space squeeze above mean residual.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.65 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Harvestable-space bonus: 15..=55 band hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && pr_u >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress)
                * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 11.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalties with compensating low-dead-space reward.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        if dead_frac <= 0.1 && pr_u > 0 {
            score -= 14.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual comparison with consolidation pressure.
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling: strong resistance unless the item is huge
    // or no fit exists; scale with fragmentation and progress.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        // Fresh-bin resistance when existing bins host the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && pr_u >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // Preserve near-exact fits in open bins rather than opening fresh.
        if fitting_bins_count >= 1 && pr_u > 0 && pr_u <= 8 {
            score += 30.0 * (1.0 - pr_u as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge.
        if fitting_bins_count >= 2 && large_item > 0.8 {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && large_item <= 0.6 {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins with large residual less when fill ratio is high.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // Penalize small dead space that nothing can use later (dead zone below 10).
    if post_residual < 10 {
        score -= 8.0; // killing a bin's residual entirely is good
    } else if post_residual <= 20 {
        score += 4.0; // awkward dead zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, this bin
    // is better saved for the next item — penalize using it now.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score += 15.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 6.0; // next item would nearly seal this bin; prefer another bin now
        } else if bin_residual >= next_item_size && bin_residual - next_item_size < 10
            && post_residual >= 10 {
            score -= 6.0; // this bin can seal the NEXT item; keep it roomy
        }
    }

    // New-bin candidate handling: a fresh empty bin should only win when existing
    // fits are poor or the item is small relative to mean residual slack.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More open bins with slack -> prefer reusing them.
        score += 3.0 * (open_bins_count as f64).sqrt();
        // If mean residual is large, opening new bins is wasteful.
        score += 0.3 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Tiny items fit anywhere; never open a bin for them.
        if item_size <= 15 {
            score += 40.0;
        }
        // If many bins fit the item, no need for a new one.
        score += 5.0 * fitting_bins_count as f64;
    } else {
        // Existing bin: slightly reward bins below mean residual (loose bins)
        // to balance load across bins.
        if (bin_residual as f64) > mean_residual {
            score -= 2.0;
        }
    }

    // Mild time-horizon modulation: early on, be pickier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

