        score -= 15.0 * (1.0 - fits.min(1.0)) * (1.0 - t);
    }

    // Last-chance bonus: only one bin fits, smooth reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + t);
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly late (prefer packing into existing bins as stream progresses).
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * t + 2.0 * open_bins_count as f64 * t;
    } else {
        // Favor bins with residual below mean (denser bins) via smooth coupling.
        score += 5.0 * (pr - mean_residual) / cap * (1.0 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
