    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Tightened fit ladder with sharper near-exact rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 370.0;
    } else if post_residual <= 5 {
        score -= 165.0;
    } else if post_residual <= 8 {
        score -= 120.0;
    } else if post_residual < 16 {
        score += 24.0;
    } else if post_residual < 30 {
