        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // Fresh-bin resistance when existing bins host the item near-exactly.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 30.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // GEN 43: fresh-bin resistance when an existing bin's post residual
        // exactly matches the next item — protecting chain setups outweighs
        // opening fresh space.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual == next_item_size {
            score += 40.0 * (0.5 + 0.5 * progress);
        }
        // GEN 43: soften resistance when the current item would strand a wide
        // band (post residual 20..=40) in every fitting bin — fresh bin wins.
        if fitting_bins_count >= 1 && pr >= 20.0 && pr <= 40.0
            && next_item_size > 0 && post_residual > next_item_size
            && (post_residual - next_item_size) > 12 {
            score -= 26.0 * progress;
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to fit even the smallest
    // plausible item (size 1..100 unknown distribution -> treat < 10 as dead),
    // and increasingly penalized as it approaches the dead zone.
    if post_residual < 10 {
        score += 60.0; // fully dead gap: worst outcome
    } else if post_residual < 25 {
        // small gap: likely dead unless a small item arrives
        score += 35.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    } else if post_residual < 50 {
        // medium gap: mildly risky, usable by many items
        score += 8.0;
    }

    // Reward near-perfect fits: the smaller the post_residual relative to bin
    // size, the better (complementary fit bonus).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Open-bin pressure: discourage spreading across many bins when few
    // alternatives exist; encourage using existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly (perfect two-step packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use the leftover: mild penalty proportional to gap
            score += 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous, easier future packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins is poor. Give it a moderate baseline so it loses to
    // good fits but beats terrible ones.
    if bin_residual == bin_capacity {
        score += 25.0;
        // early in the stream, opening bins is cheaper (more future items to fill)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
