}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Near-match within a small tolerance also rewarded, scaled by closeness.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff <= 6 {
            score -= 60.0 * (1.0 - diff as f64 / 7.0);
        }
    }

    // Penalize unusable dead space: post_residual too small for the smallest item.
    if post_residual < 1 {
        score += 200.0;
    } else if post_residual <= 3 {
        score += 40.0 * (4.0 - post_residual as f64);
    }

    // Tight fits (small post_residual) are generally good: reward exponentially.
    score -= 30.0 * (-post_residual as f64 / 15.0);

    // Relative-to-mean coupling: bins with residual well below mean are precious;
    // using them is good, so reward placing into below-mean-residual bins.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current bin would leave a very large, awkward residual.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred for decent fits.
        score += 25.0;
        // But if the item barely fits nowhere well (large post_residual in any
        // open bin would be >= this), allow the new bin when it creates a
        // clean residual matching the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 150.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // Many open bins already: discourage more.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pressure = (open_bins_count as f64).ln().max(1.0) * (0.5 + 0.5 * progress);

    // Tightened fit ladder: deepen exact/near-exact rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 380.0;
    } else if post_residual <= 5 {
        score -= 165.0;
    } else if post_residual <= 8 {
        score -= 122.0;
    } else if post_residual < 16 {
        score += 26.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 530.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 185.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap as f64 / 50.0).max(0.0);
            }
            if fitting_bins_count <= 2 {
                score -= 58.0;
            }
            if gap >= next_item_size {
                score -= 34.0;
            }
            if gap >= (next_item_size / 2) && progress > 0.4 {
                score -= 16.0 * progress;
            }
            if gap > 0 && post_residual >= 2 * next_item_size {
                score -= 26.0 * (1.0 - progress);
            }
            if post_residual >= 3 * next_item_size && progress < 0.5 {
                score -= 19.0 * (1.0 - progress);
            }
            if post_residual >= 2 * next_item_size + 1 && progress > 0.25 {
                score -= 12.0 * progress;
            }
            if gap >= 12 && gap <= 30 && progress > 0.3 {
                score -= 16.0 * progress * (1.0 - gap as f64 / 31.0);
            }
            if gap >= 1 && gap <= 4 && progress > 0.2 {
                score -= 30.0 * (1.0 - gap as f64 / 5.0) * progress;
            }
            if post_residual >= 3 * next_item_size && progress > 0.3 {
                score -= 11.0 * progress;
            }
            // Chain-fit gradient: tighter leftover after hosting next item.
            if gap > 0 {
                let tightness = 1.0 - gap as f64 / (cap - next_item_size as f64).max(1.0);
                score -= 26.0 * tightness * (0.4 + 0.6 * progress)
                    / (fitting_bins_count.max(1) as f64).sqrt();
            }
            // Exact double-fit bonus.
            if post_residual >= 2 * next_item_size
                && post_residual < 3 * next_item_size
                && progress > 0.25 {
                score -= 16.0 * (1.0 - progress) * (1.0 - pr / cap);
            }
            // Perfect two-chain — residual exactly 2x next item is ideal.
            if post_residual as u64 == 2 * next_item_size as u64 {
                score -= 42.0 * (0.5 + 0.5 * progress);
            }
            // Triple-chain lookahead — residual hosting next item thrice
            // plus a small remainder is a compounding target.
            if post_residual as u64 >= 3 * next_item_size as u64
                && (post_residual as u64 - 3 * next_item_size as u64) <= 4
                && progress > 0.3 {
                score -= 24.0 * progress;
            }
            // GEN 43: quad-chain seeding — residual that can host the next
            // item four times with a small remainder.
            if post_residual as u64 >= 4 * next_item_size as u64
                && (post_residual as u64 - 4 * next_item_size as u64) <= 3
                && progress > 0.2 {
                score -= 20.0 * progress;
            }
        } else {
            let waste_frac = (next_item_size - post_residual) as f64 / cap;
            let deadness = if pr < 10.0 { 1.5 } else { 1.1 };
            score += (next_item_size - post_residual) as f64 * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 255.0 * waste_frac * (1.0 - progress);
            if next_item_size - post_residual <= 6 {
                score -= 18.0;
            }
            if pr >= 4.0 && pr <= 12.0 {
                score -= 28.0 * (1.0 - (pr - 4.0) / 8.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 21.0 * (1.0 - miss as f64 / 11.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            if miss > 0 && miss <= 3 {
                score += 13.0 * (1.0 - progress);
            }
            if miss > 10 && miss <= 18 && progress > 0.4 {
                score += 13.0 * progress;
            }
            if miss > 0 && miss <= 15 && progress > 0.35 {
                score -= 11.0 * (1.0 - miss as f64 / 16.0) * progress;
            }
            // Near-miss severity ramp with scarcity weighting.
            if miss > 0 {
                let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
                score += 33.0 * (miss as f64 / cap) * (0.6 + 0.8 * progress) * scarcity;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Fragmentation slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 138.0;
    }
    if bin_residual > 0 && post_residual > 0 {
        let ir = item_size as f64 / bin_residual.max(1) as f64;
        if ir > 0.72 && post_residual < 14 {
            score += 24.0 * (ir - 0.72);
        }
        if post_residual < 5 {
            score -= 32.0;
        }
        if pr >= 10.0 && pr <= 20.0 {
            score += 10.0 * (1.0 - (pr - 10.0) / 10.0) * (0.6 + 0.4 * (1.0 - progress));
        }
        if pr > 10.0 && pr <= 25.0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (pr - 10.0) / 15.0);
        }
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 44.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
        if waste_ratio < 0.6 && bin_residual as f64 > 0.85 * cap {
            score += 20.0 * (0.6 - waste_ratio) * (0.5 + progress);
        }
        if progress > 0.35 && post_residual > 0 && post_residual < 4 {
            score += 48.0 * (1.0 - progress);
        }
        if pr >= 20.0 && pr <= 50.0 {
            score -= 10.0 * (1.0 - (pr - 20.0) / 30.0) * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && pr == (2 * next_item_size) as f64 {
            score -= 38.0;
        }
        if pr >= 25.0 && pr <= 45.0 && next_item_size > 0 && next_item_size <= 25 {
            score -= 14.0 * (1.0 - (pr - 25.0) / 20.0) * (0.4 + 0.6 * progress);
        }
        if progress > 0.6 && next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
            score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);
        }
        if progress > 0.45 && pr > 0.25 * cap {
            score += 20.0 * ((pr / cap) - 0.25) * progress;
        }
        if progress > 0.75 && pr > 0.15 * cap && next_item_size > 0 && post_residual < next_item_size {
            score += 26.0 * ((pr / cap) - 0.15) * (progress - 0.75) * 4.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.5 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 14.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 32.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Quadratic dead-space squeeze above mean residual — GEN 43 sharpened:
        // lower threshold, stronger late-stream weighting.
        if pr > mean_residual + 6.0 {
            let excess = pr - mean_residual - 6.0;
            score += 0.72 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Harvestable-space bonus: 15..=55 band hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 12.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty — bins whose post residual exceeds
        // a growing fraction of capacity are poor targets mid-to-late stream.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        // Penalize the 0.12..0.3 band late in the stream when no item can fill it.
        if dead_frac > 0.12 && dead_frac <= 0.3 && progress > 0.5
            && next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (dead_frac - 0.12) * (progress - 0.5) * 3.0;
        }
        // GEN 43: extend dead-band penalty earlier when the residual is
        // unreachable by the next item and scarcity is high.
        if dead_frac > 0.15 && dead_frac <= 0.3 && progress > 0.3
            && next_item_size > 0 && post_residual < next_item_size
            && fitting_bins_count <= 2 {
            score += 12.0 * (dead_frac - 0.15) * (progress - 0.3) * 3.0;
        }
        // Reward bins whose dead-space fraction stays below 0.1 after placement.
        if dead_frac <= 0.1 && post_residual > 0 {
            score -= 16.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // GEN 43: ultra-tight residual bonus — post residual within 3 of the
        // item size means near-perfect compaction; reward extra.
        if next_item_size > 0 && post_residual >= next_item_size
            && post_residual - next_item_size <= 3 {
            score -= 14.0 * (1.0 - (post_residual - next_item_size) as f64 / 4.0)
                * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 96.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // Fresh-bin resistance when existing bins can host the item
        // with near-exact fit (post residual <= 8), preserving those tight fits.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 32.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // GEN 43: resist fresh bin when the item exactly completes an existing
        // bin (post_residual == 0 would mean perfect fill).
        if fitting_bins_count >= 1 && post_residual == 0 {
            score += 120.0;
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 * (1.0 - tightness.min(1.0));

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + gap);
    }
    // If next item cannot use the leftover, penalize large dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening new bins when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that grows with open bins and stream progress.
        score += 25.0 + 3.0 * open_bins_count as f64 + 40.0 * progress;
        // But if no bin would leave a good residual, new bin is fine: soften when mean residual is low.
        if mean_residual < 10.0 {
            score -= 20.0;
        }
    } else {
        // Discard placements into bins with very low residual that fragment space.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
        // Mild preference for bins below mean residual (balance residuals).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins harder near the end.
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 340.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score -= 110.0;
    }

    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 540.0;
        } else if gap > 0 {
            let g = gap as f64;
            // Tight chain-fit reward decaying with gap.
            score -= 200.0 * (1.0 - (g / 12.0).min(1.0)) * (0.5 + 0.5 * progress);
            // Double-fit bonus: residual can host next item twice.
            if post_residual as u64 >= 2 * next_item_size as u64 {
                score -= 40.0 * (0.4 + 0.6 * progress);
            }
            // Triple-chain lookahead with small remainder.
            if post_residual as u64 >= 3 * next_item_size as u64
                && (post_residual as u64 - 3 * next_item_size as u64) <= 4
                && progress > 0.3 {
                score -= 20.0 * progress;
            }
            // Scarcity bonus when few bins can host.
            if fitting_bins_count <= 2 {
                score -= 55.0;
            }
        } else {
            // Dead space too small for next item: penalize severity.
            let miss = (-gap) as f64;
            let scarcity = 1.0 + 1.5 / (fitting_bins_count.max(1) as f64);
            score += miss * (0.5 + 0.3 * (1.0 - progress)) * scarcity;
            if miss <= 3 {
                score += 12.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 330.0;
    }

    // Penalize tiny unusable slivers more than large gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 145.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Mean-residual anchoring: prefer bins with above-average residual.
    if pr > mean_residual {
        score -= (pr - mean_residual) * 0.32;
    } else {
        score += (mean_residual - pr) * 0.32;
    }

    // Dead-space fraction penalties/rewards.
    let dead_frac = pr / cap;
    if dead_frac > 0.3 && progress > 0.3 {
        score += 30.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
    }
    if dead_frac <= 0.1 && post_residual > 0 {
        score -= 13.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
    }

    // Residual-efficiency term: dense packing reward, scarcity-scaled.
    let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
    score -= 10.0 * fill_frac * (0.4 + 0.6 * progress)
        * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64).ln().max(1.0) * (item_size as f64) * 0.045 * (0.5 + progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score += 60.0 + 130.0 * fragmentation;
        } else {
            let penalty = 70.0
                + 190.0 * fragmentation
                - 160.0 * large_item
                - 50.0 * progress
                + 35.0 * (open_bins_count as f64).ln().max(0.0);
            score += penalty.max(0.0);
        }
        // Fresh bin can host both current and next item: allow early.
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 250.0 * (1.0 - progress);
        }
        // Resist opening bins when an existing near-exact fit exists.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 32.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // Resist when existing bins leave harvestable mid-band space.
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 22.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only for huge items late.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 22.0;
        }
        // Late-stream strong resistance when decent fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 30.0 * (progress - 0.7) * 3.0;
        }
        // Resist when existing bin hosts next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 18.0 * progress;
        }
        // Small items late: strongly resist new bins.
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 26.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
