    // Tightened fit ladder: deepen exact/near-exact rewards, sharpen sliver penalty.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 372.0;
    } else if post_residual <= 5 {
        score -= 164.0;
    } else if post_residual <= 8 {
        score -= 122.0;
    } else if post_residual < 16 {
        score += 28.0;
    } else if post_residual < 30 {
        score += 5.0;
    } else {
        score -= 20.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 540.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 192.0 * (1.0 - gap as f64 / 6.0);
            } else {
                score -= 124.0 * (1.0 - gap as f64 / 50.0).max(0.0);
