        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 20.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 8.0 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 12.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 36.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        // Mid-band dead-space penalty late in the stream.
        if dead_frac > 0.12 && dead_frac <= 0.3 && progress > 0.5
            && next_item_size > 0 && post_residual < next_item_size {
            score += 17.0 * (dead_frac - 0.12) * (progress - 0.5) * 3.0;
        }
        // Reward bins whose dead-space fraction stays below 0.1.
        if dead_frac <= 0.1 && post_residual > 0 {
            score -= 15.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // GEN 44: residual-orphan penalty — a residual that cannot host the next
        // item AND is below the mean is a stranded fragment; penalize with
        // progress so late-stranded space is avoided strongly.
        if next_item_size > 0 && post_residual < next_item_size && pr < mean_residual {
            score += 12.0 * (1.0 - pr / mean_residual.max(1.0)) * progress;
        }
        // GEN 44: pair-completion lookahead — residual equals capacity minus a
