        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 25.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 33.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 21.0 * progress;
        }
        // Fresh-bin resistance when existing bins offer near-exact fits.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 31.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // GEN 44: fresh-bin resistance when an existing bin's post-residual
        // exactly matches the next item — opening a bin would destroy a
        // guaranteed perfect chain placement.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual == next_item_size {
            score += 46.0 * (0.5 + 0.5 * progress);
        }
        // GEN 44: fresh-bin resistance when the mean residual still exceeds the
        // item size — stranded space elsewhere is cheaper to fill first.
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 {
            score += 14.0 * ((mean_residual - item_size as f64) / cap).min(0.5) * (0.5 + progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, but discounted early (dead space matters more later)
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Smooth non-linear coupling: reward tight fits via cubic of normalized post residual
    score -= 40.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn) * (1.0 + progress);

    // Penalize large post residual quadratically, weighted by stream progress
    score += 25.0 * prn * prn * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post residual accommodates the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack) * (1.0 - progress * 0.5);
        } else {
            let gap = (nxt - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Mild penalty for opening new bins when many bins are open and residual mean is high
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * (mean_residual / cap) * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += 5.0 * ((bin_residual as f64) - mean_residual) / cap;

    score
}

