            score += 20.0 * ((pr / cap) - 0.25) * progress;
        }
        if progress > 0.75 && pr > 0.15 * cap && next_item_size > 0 && post_residual < next_item_size {
            score += 26.0 * ((pr / cap) - 0.15) * (progress - 0.75) * 4.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.5 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 14.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 32.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 18.0 * (0.5 + 0.5 * progress);
        }
        // Quadratic dead-space squeeze above mean residual.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.68 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Harvestable-space bonus: 15..=55 band hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Mean-residual anchoring.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 && pr > 0.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 11.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalty — bins whose post residual exceeds
        // a growing fraction of capacity are poor targets mid-to-late stream.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        // Penalize the 0.12..0.3 dead band late when no item can fill it.
        if dead_frac > 0.12 && dead_frac <= 0.3 && progress > 0.5
            && next_item_size > 0 && post_residual < next_item_size {
            score += 16.0 * (dead_frac - 0.12) * (progress - 0.5) * 3.0;
        }
        // Reward bins whose dead-space fraction stays below 0.1.
        if dead_frac <= 0.1 && post_residual > 0 {
            score -= 15.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // GEN 44: residual modularity — bins whose post residual decomposes
        // cleanly into the next item's size chain are prime targets, since
        // they can absorb multiple future copies without creating slivers.
        if next_item_size > 0 && next_item_size <= 30 && post_residual > 0 {
            let k = pr as u64 / next_item_size as u64;
            let rem = pr as u64 % next_item_size as u64;
            if k >= 1 && rem <= 2 {
                score -= 12.0 * (k.min(3) as f64) * (0.4 + 0.6 * progress);
            }
        }
        // GEN 44: late-stream sliver quarantine — a residual that no realistic
        // item can fill (below the smallest plausible next item) late in the
        // stream is pure waste; steer away from creating it.
        if progress > 0.55 && post_residual > 0 && post_residual < 6
            && next_item_size > post_residual {
            score += 20.0 * (6.0 - pr) * (progress - 0.55) * 2.0;
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                - 66.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 96.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 74.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 28.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 36.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 22.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 18.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 58.0 * (1.0 - item_size as f64 / 71.0);
        }
        // Fresh-bin resistance tied to harvestable space (15..=45).
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Allow fresh bin only when the item is huge; otherwise resist.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // Late-stream resistance when a good fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Extra resistance when an existing bin hosts the next item too.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual >= next_item_size && progress > 0.4 {
            score += 20.0 * progress;
        }
        // Fresh-bin resistance when existing bins can host the item
        // with near-exact fit (post residual <= 8), preserving tight fits.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 30.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // GEN 44: fresh-bin resistance scaled by how much of the current
        // item's size class already exists in open bins — if a similar-size
        // item was recently placed, an existing bin likely hosts its class.
        if fitting_bins_count >= 1 && progress > 0.3 && item_size <= 40 {
            score += 14.0 * (1.0 - item_size as f64 / 41.0) * (progress - 0.3) * 2.0;
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>=1) can
    // meaningfully use are heavily penalized. Small unusable gaps are worse
    // than large leftover space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // awkward mid-range gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless the new bin
    // would be nearly full immediately.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; waived if item nearly fills it.
        score += 30.0 - 30.0 * fill;
        // If many bins are already open, be even more reluctant to add one.
        score += open_bins_count as f64 * 2.0;
        // But if no existing bin fits well (this is the only candidate),
        // opening a fresh bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // Mild reward for consolidating into existing bins when many are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement strongly (chaining placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: residual is likely dead space.
            score += 6.0;
        }
    }

    // Early in the stream, slightly prefer keeping bins tidy (larger residuals);
    // late in the stream, squeeze everything into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill);

    // Prefer bins whose residual is below average (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect / near-perfect fit ladder (borrowed compaction gradient).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 340.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score -= 110.0;
    } else if post_residual < 16 {
        score += 24.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        score -= 16.0;
    }

    // Lookahead: how well does the leftover host the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 540.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 5 {
                score -= 190.0 * (1.0 - gap / 6.0);
            } else {
                score -= 120.0 * (1.0 - gap / 50.0).max(0.0);
            }
            // Exact double-fit target: residual == 2x next item.
            if post_residual as u64 == 2 * next_item_size as u64 {
                score -= 46.0 * (0.5 + 0.5 * progress);
            }
            if post_residual >= 2 * next_item_size && progress > 0.25 {
                score -= 16.0 * (1.0 - progress) * (1.0 - pr / cap);
            }
            // Chain-fit tightness gradient, scarcity-scaled.
            if gap > 0 {
                let tightness = 1.0 - gap / (cap - next_item_size as f64).max(1.0);
                score -= 26.0 * tightness * (0.4 + 0.6 * progress)
                    / (fitting_bins_count.max(1) as f64).sqrt();
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            let waste_frac = miss / cap;
            let deadness = if pr < 10.0 { 1.5 } else { 1.1 };
            score += miss * (0.42 + 0.34 * (1.0 - progress)) * deadness
                + 255.0 * waste_frac * (1.0 - progress);
            // Near-miss severity ramp with scarcity weighting.
            let scarcity = 1.0 + 1.6 / (fitting_bins_count.max(1) as f64);
            score += 33.0 * (miss / cap) * (0.6 + 0.8 * progress) * scarcity;
            if miss <= 3 {
                score += 13.0 * (1.0 - progress);
            }
            if miss > 10 && miss <= 18 && progress > 0.4 {
                score += 13.0 * progress;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Fragmentation slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 138.0;
    }

    if bin_residual > 0 && post_residual > 0 {
        // Harvestable-space bonus: mid-band residual hosting next item.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress)
                * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // Quadratic dead-space squeeze above mean residual.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.65 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // Residual-efficiency term — dense packing reward, scarcity-scaled.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 11.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.8 / (fitting_bins_count.max(1) as f64));
        // Dead-space ratio penalties / rewards.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 34.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        if dead_frac > 0.12 && dead_frac <= 0.3 && progress > 0.5
            && next_item_size > 0 && post_residual < next_item_size {
            score += 16.0 * (dead_frac - 0.12) * (progress - 0.5) * 3.0;
        }
        if dead_frac <= 0.1 && post_residual > 0 {
            score -= 14.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // Mean-residual anchoring: prefer residuals near the mean.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 {
            score -= 7.5 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
        // Waste-ratio guard for mostly-empty bins.
        let waste_ratio = pr / (bin_residual as f64).max(1.0);
        if waste_ratio < 0.35 && bin_residual as f64 > 0.5 * cap {
            score += 44.0 * (0.35 - waste_ratio) * (1.2 - progress);
        }
    } else if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE: calibrated resistance.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 136.0 * fragmentation;
        } else {
            let penalty = 72.0
                + 195.0 * fragmentation
                - 170.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 52.0 * progress
                + 39.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        // Resist opening a bin when a tight fit already exists.
        if fitting_bins_count >= 1 && post_residual > 0 && post_residual <= 8 {
            score += 30.0 * (1.0 - post_residual as f64 / 9.0) * (0.4 + 0.6 * progress);
        }
        // Fresh-bin resistance in the harvestable band.
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 24.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // Late-stream resistance when a decent fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 32.0 * (progress - 0.7) * 3.0;
        }
        // Huge items deserve fresh bins.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
        // New bin that can host both current and next item is valuable early.
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 262.0 * (1.0 - progress);
        }
        // Small items late: strongly prefer existing bins.
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 28.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        // Next item won't fit anywhere after this placement — resist new bin.
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.5 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.034 * (0.5 + progress);

    score
}

