        }
        if progress > 0.6 && next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
            score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);
        }
        if progress > 0.45 && pr > 0.25 * cap {
            score += 18.0 * ((pr / cap) - 0.25) * progress;
        }
        if progress > 0.75 && pr > 0.15 * cap && next_item_size > 0 && post_residual < next_item_size {
            score += 24.0 * ((pr / cap) - 0.15) * (progress - 0.75) * 4.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 9.0 * unmet * (0.35 + 0.65 * progress) / (1.0 + (pr / 20.0));
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap >= 1 && gap <= 10 && progress > 0.15 {
                score -= 12.0 * (1.0 - gap as f64 / 11.0) * (0.5 + 0.5 * progress);
            }
        }
        if progress > 0.85 && next_item_size > 0 && post_residual < next_item_size {
            score += 30.0 * ((next_item_size - post_residual) as f64 / next_item_size as f64) * (progress - 0.85) * 6.0;
        }
        if next_item_size > 0 && pr >= (2 * next_item_size) as f64 && pr <= (2 * next_item_size + 4) as f64 && progress > 0.2 {
            score -= 16.0 * (0.5 + 0.5 * progress);
        }
        // GEN 25/45: quadratic dead-space squeeze — penalize post-residuals
        // exceeding the mean residual, growing quadratically in progress.
        if pr > mean_residual + 8.0 {
            let excess = pr - mean_residual - 8.0;
            score += 0.62 * excess * excess / cap * (0.3 + 0.7 * progress * progress);
        }
        // GEN 25/45: harvestable-space bonus — residual in 15..=55 band that
        // can host the next item is prime consolidation space; strengthened.
        if pr >= 15.0 && pr <= 55.0 && next_item_size > 0 && post_residual >= next_item_size {
            let usable = 1.0 - ((pr - next_item_size as f64) / 40.0).clamp(0.0, 1.0);
            score -= 19.0 * usable * (0.3 + 0.7 * progress) * (1.0 + 0.1 * (open_bins_count as f64).ln().max(0.0));
        }
        // GEN 45: dense-packing reward — high fill fraction of the residual
        // is rewarded, scaled by scarcity of alternatives.
        let fill_frac = 1.0 - pr / (bin_residual as f64).max(1.0);
        score -= 10.0 * fill_frac * (0.4 + 0.6 * progress)
            * (1.0 + 0.7 / (fitting_bins_count.max(1) as f64));
        // GEN 45: dead-space ratio penalties and rewards.
        let dead_frac = pr / cap;
        if dead_frac > 0.3 && progress > 0.3 {
            score += 32.0 * (dead_frac - 0.3) * (progress - 0.3) * 2.5;
        }
        if dead_frac <= 0.1 && post_residual > 0 {
            score -= 13.0 * (0.1 - dead_frac) * (0.5 + 0.5 * progress);
        }
        // GEN 45: mean-residual anchoring — prefer residuals near the mean.
        let dev = (pr - mean_residual).abs();
        if dev < 6.0 {
            score -= 7.0 * (1.0 - dev / 6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mean-residual comparison.
    if bin_residual as f64 > mean_residual {
        score += 6.5 * pressure;
    } else {
        score -= 4.5 * pressure;
    }

    // New-bin candidate: only attractive when forced or the item is large
    // and existing fits are poor; otherwise resist opening fresh bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        let next_large = (next_item_size as f64 / cap).min(1.0);
        if fitting_bins_count == 0 {
            score -= 34.0;
        } else if fitting_bins_count == 1 {
            score += 62.0 + 132.0 * fragmentation;
        } else {
            let penalty = 70.0
                + 190.0 * fragmentation
                - 168.0 * large_item
                + 40.0 * (open_bins_count as f64).ln().max(0.0)
                - 50.0 * progress
                - 64.0 * next_large * (1.0 - progress)
                + 22.0 * (1.0 - large_item) * (1.0 - fragmentation)
                + 38.0 * progress * fragmentation;
            score += penalty.max(0.0);
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 258.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual == next_item_size && progress > 0.5 {
            score -= 92.0 * progress;
        }
        if fitting_bins_count >= 2 {
            score += 15.0 * fragmentation * (1.0 - progress);
        }
        if fitting_bins_count >= 1 && pr > 0.0 && pr <= 6.0 {
            score += 70.0;
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            score += 26.0 * (1.0 - post_residual as f64 / cap);
        }
        if fitting_bins_count >= 1 && progress > 0.5 && pr > 0.0 && pr <= 12.0 {
            score += 34.0 * (1.0 - pr / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.3 && pr > 12.0 && pr <= 24.0 {
            score += 20.0 * (1.0 - (pr - 12.0) / 13.0);
        }
        if fitting_bins_count >= 1 && progress > 0.2 && pr >= 24.0 && pr <= 40.0
            && next_item_size > 0 && next_item_size <= pr {
            score += 16.0 * (1.0 - (pr - 24.0) / 17.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 3 && item_size <= 30 {
            score += 18.0 * ((fitting_bins_count as f64 - 2.0).min(4.0)) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 1 && progress > 0.6 && item_size <= 50 {
            score += 27.0 * (progress - 0.6) * 2.5 * (1.0 - item_size as f64 / 51.0);
        }
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual < next_item_size {
            let unmet = (next_item_size - post_residual) as f64;
            score += 15.0 * (unmet / cap) * (0.5 + progress);
        }
        if fitting_bins_count >= 1 && progress > 0.9 && item_size <= 70 {
            score += 55.0 * (1.0 - item_size as f64 / 71.0);
        }
        // GEN 25/45: fresh-bin resistance tied to harvestable space — an
        // existing bin's post-fit residual in 15..=45 is still fillable.
        if fitting_bins_count >= 1 && pr >= 15.0 && pr <= 45.0 {
            score += 23.0 * (1.0 - ((pr - 15.0) / 30.0).abs()) * (0.4 + 0.6 * progress);
        }
        // GEN 45: late-stream resistance when a decent fit exists.
        if fitting_bins_count >= 1 && progress > 0.7 && item_size as f64 <= 0.6 * cap {
            score += 30.0 * (progress - 0.7) * 3.0;
        }
        // GEN 45: huge items deserve fresh bins.
        if fitting_bins_count >= 2 && item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
    } else {
        score += (mean_residual - bin_residual as f64).max(0.0) * (0.48 + 0.3 * progress);
    }

    // Consolidation pressure grows with stream progress.
    score -= (open_bins_count as f64) * (item_size as f64) * 0.033 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
